quests[80203] = { id = 80203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In bester Gesellschaft", description = "<Die Neruberin flüstert und beobachtet die Wachen hinter Euch mit wachsamem Blick.>\n\nDie Weberin hat Euch geschickt, ja? Ich bin hergekommen, um die Zustimmung des Magistrats für den Aufstieg zu erbitten, um die gehobenen Kreise zu infiltrieren, versteht sich.\n\nDoch er wird vermisst. Das kommt äußerst ungelegen.\n\nIch muss mich umhören. Ihr seid genau das, worauf ich gewartet habe! Ihr solltet Euch als... meine Dienerschaft ausgeben. Oder als mein Haustier? Was immer Euch lieber ist.\n\nIch komme so selten in den Genuss, an der Seite von Freunden zu arbeiten. Wir werden viel Spaß zusammen haben.", sourceObjective = "Helft Oratorin Tx'itk, sich nach dem Magistrat zu umzuhören.", progress = "Ich habe ein paar langjährige Freunde, die vor kurzem aufgestiegen sind. Bestimmt hat einer von denen etwas gehört, das er gern mit uns teilen würde. Um der alten Zeiten willen.\n\nUnd falls nicht, ist es der Neid auf mich und mein schickes, neues Haustier, der sie dazu inspirieren wird, mir zu sagen, was ich wissen will.", completion = "Ich wusste, dass der Aufstieg die Leute verändert, aber... Sie waren meine Freunde. Und jetzt wollen sie sich nicht mal mehr mit mir blicken lassen.\n\nDa frage ich mich... ob auch ich mich verändern werde, sollte ich mit all dem Erfolg haben.\n\n<Tx'itk schüttelt den Kopf.>\n\nAber das ist nicht wichtig. Ich werde tun, was nötig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[80204] = { id = 80204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spionage und Bauchrednerei", description = "Der Strippenzieher ist unsere heißeste Spur bei der Suche nach dem Magistrat.\n\nAber liegt es an mir oder wirken diese Puppen... erschreckend lebensecht? Wenn dieser Künstler hinter dem Verschwinden des Magistrats steckt, will er sich wohl kaum eine Vorstellung im Puppentheater ansehen.\n\nWir sollten die Werkstatt des Strippenziehers untersuchen und ihm ein paar Fragen stellen oder zumindest seine Sachen durchstöbern. Nur ein bisschen. Bis wir etwas gefunden haben.\n\nIhr werdet bei dieser Scharade wieder Eure eher unwürdige Rolle spielen müssen. Aber es wird sich für uns lohnen.", sourceObjective = "Untersucht die Werkstatt des Strippenziehers.", progress = "<Oratorin Tx'itk senkt ihre Stimme.>\n\nHier stimmt etwas nicht. Spielt weiter mit. Mal sehen, was wir sonst noch herausfinden.", completion = "Der Magistrat schwebt definitiv in Gefahr. Wir müssen schnell handeln, ehe ich meine Chance auf den Aufstieg verliere.", sourceObjectiveStatus = "unverified-source-field" }
quests[80205] = { id = 80205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strippen ziehen", description = "Stellt Euch das nur einmal vor! Überkrabbler, Kriegsgefangene, Zivilisten, andere Neruber und wichtige Adlige werden entführt und vor den Augen des Magistrats zu Marionetten gemacht.\n\nDas ist schrecklich, und genau das, was ich gebraucht habe! Wenn wir den Magistrat vor diesem Schicksal bewahren können, ist er mir etwas schuldig. Nicht nur dafür, dass ich ihm das Leben gerettet habe, sondern auch dafür, über all das Stillschweigen zu bewahren.\n\nWir gehen also ins Theater. Wenn Ihr den Strippenzieher ablenken könnt, befreie ich den Obersten Erheber Etak'kaht aus seinen Fängen.\n\nHoffentlich ist er noch nicht Teil der Vorführung.", sourceObjective = "Stellt den Strippenzieher, um den Obersten Erheber Etak'kaht zu retten.", completion = "Ausgezeichnet. Eine bessere Gelegenheit, die Aufmerksamkeit des Magistrats zu erregen, könnte man sich nicht träumen lassen. Und die Weberin wird erfreut sein zu hören, dass wir ihn auf unbestimmte Zeit in der Tasche haben.\n\nIch mache mich dann wohl auf zum Transformatorium.\n\n<Tx'itk erschaudert ein wenig.>\n\nIch... Meine Entschlossenheit darf nicht ins Wanken geraten. Die Weberin hat es so verlangt. Ich werde ihre Augen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[80206] = { id = 80206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnade den Marionetten", description = "Es ist perfekt! Der Strippenzieher will Euch so sehr seiner Sammlung hinzufügen, dass er uns buchstäblich eingeladen hat, den Magistrat zu retten.\n\nIch will nicht andeuten, dass ich Euch die ganze Zeit als Köder eingesetzt habe, aber... Sagen wir einfach, gewisse Risiken haben sich ausgezahlt.\n\nSelbst ein so fähiger Künstler muss einen Weg haben, eventuelle Fehler zu beheben. Es muss hier irgendwo ein Gegengift für diesen Lähmungswirkstoff geben!\n\nFindet es. Und vielleicht sollten wir es testen, bevor wir es beim Magistrat einsetzen. Nur für alle Fälle.", sourceObjective = "Findet das Lähmungsheilserum des Strippenziehers.", progress = "Ich würde mir ja Sorgen machen, dass wir zu lange brauchen, aber bedenkt man, wie dramatisch der Strippenzieher ist, wird er das Spektakel nicht ohne uns beginnen.\n\nWir sollten auf etwas... recht Unangenehmes vorbereitet sein, wenn wir das Theater erreichen.", completion = "Genau, wonach wir suchen.\n\nUnd dass ich Euch als Köder eingesetzt habe... Ihr wisst, dass das in unserer Branche nichts Persönliches ist.\n\nIch habe von Anfang an ehrlich zugegeben, dass Ihr das Statussymbol seid, dass ich in diesen Kreisen benötige, um die Aufgestiegenen sozial zu manipulieren.\n\nWenn es eine Sache gibt, auf die ich mich verlassen kann, dann die Fähigkeit der Aufgestiegenen, über andere ausgeübte Macht zu begehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[80207] = { id = 80207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie skandalös!", description = "Habt Ihr irgendetwas gesehen?\n\nIch war gerade wegen eines Schmuckauftrags in den Schmiedegründen unterwegs, als plötzlich alle brüllten, als würde der Kernweg angegriffen - wieder mal.\n\nAber das war es nicht...\n\nEinige Friedensbewahrer rannten auf das Depot zu, wo die Fertigungslieferungen aus den Tiefen hochgeschickt werden. Ich wette, es hat etwas mit den Maschinenflüsterern zu tun!\n\nDie Friedensbewahrer schickten alle weg, bevor ich sehen konnte, was passiert war. Aber vielleicht könnt Ihr einen Blick erhaschen?", sourceObjective = "Untersucht den Aufruhr nahe den Schmiedegründen in Dornogal.", completion = "Geht weiter. Dies ist eine laufende... Oh, {name}, Verzeihung.\n\nWir könnten Eure Hilfe tatsächlich brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80208] = { id = 80208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trügerische Grabung" }
quests[80209] = { id = 80209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltener Vogel in Dornogal", description = "Uns wurde gemeldet, dass ein exzentrischer Arathi unsere Bürger belästigt. Wir haben nur wenig Erfahrung mit Außenstehenden, und meine Vorgesetzten fürchten sich vor einem diplomatischen Eklat.\n\nMan hat mich damit beauftragt, diesen \"Lampenanzünder\" zu finden und seine Probleme zu lösen. Ihr habt schon einmal mit den Arathi gearbeitet... Könntet Ihr mir helfen?\n\nIch habe hier eine Liste mit Irdenen, die den Lampenanzünder gemeldet haben. Ihr könnt eine Hälfte davon befragen. Zusammen können wir diesen Arathi hoffentlich finden, bevor er noch mehr Bürgern Probleme bereitet.", sourceObjective = "Befragt besorgte Bürger von Dornogal, um den Lampenanzünder der Arathi zu finden.", completion = "Das ist nicht unbedingt das, was ich erwartet habe.\n\nEr ist merkwürdig, ja, aber ein Störenfried? Eher nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[80210] = { id = 80210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefunden bei den Freien", description = "Der Lampenanzünder sucht nach seinen Arathifreunden. Der Vorarbeiter sagt, er habe eine Schiffsbauerin der Arathi nach Freyholtz geschickt.\n\nMeine Vorgesetzten bestehen darauf, dass die Friedensbewahrer Dornogal nicht verlassen dürfen... Aber mir wurde befohlen, Kaerter zu unterstützen. Und dafür muss ich die Stadt verlassen.\n\n<Leif verbirgt schnell ein Lächeln.>\n\nDann ist es beschlossen. Trefft uns in Freyholtz, wenn Ihr wollt. Ich würde mich über Eure weitere Unterstützung freuen.", sourceObjective = "Trefft Euch mit Friedensbewahrer Leif außerhalb von Freyholtz.", completion = "Die Einheimischen sind mit unserem ausländischen Gefährten wohl nicht einverstanden. Ich versuche, die Situation so gut wie möglich zu entschärfen.\n\nAber wir haben dringendere Probleme.", sourceObjectiveStatus = "unverified-source-field" }
quests[80211] = { id = 80211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Plünderung von Freyholtz", description = "Die Schiffsbauerin der Arathi war hier, doch sie ist mit den meisten aus ihrem Gefolge weitergezogen. Sie hat ein paar Arathi zurückgelassen, aber...\n\nKurz nachdem die Schiffsbauerin wegging, begannen Irdene zu verschwinden. Die Bewohner verdächtigten die Arathi, hatten aber keine Beweise. Eines Tages verließen die übrigen Arathi dann mitten in der Nacht die Stadt.\n\nDie Anwohner sagten, die Arathi wohnten im Gasthaus. Könnt Ihr Euch dort nach Hinweisen darauf umsehen, wo die Arathi sich jetzt aufhalten könnten?\n\nAngesichts der Feindseligkeit der Bewohner bleiben der Lampenanzünder und ich vorerst besser hier.", sourceObjective = "Sucht nach Hinweisen auf den Verbleib der Arathi.", completion = "Wenn ich es recht verstehe, entführen die Arathi Irdene?\n\nUnd sie töten sich außerdem gegenseitig?\n\nDas ist doch Wahnsinn!", sourceObjectiveStatus = "unverified-source-field" }
quests[80212] = { id = 80212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entführungsvereiteler", description = "Der Orden der Nacht ist eindeutig an unseren Ressourcen interessiert. Sie haben Irdene für ihre Ernte entführt und könnten es auf weitere abgesehen haben. Wir müssen sie aufhalten.\n\nDie nächste große Irdenensiedlung ist Bummelgau. Wenn der Orden mehr Arbeiter braucht, werden sie vielleicht dort welche holen.\n\nGeht schon vor, {name}. Ich muss zunächst mit Kaerter darüber sprechen, warum die Arathi das tun.", sourceObjective = "Trefft Euch mit Friedensbewahrer Leif in Bummelgau.", completion = "Wir haben zwar noch keine Arathi gesehen, aber es herrscht Unruhe in der Stadt.\n\nKaerter glaubt, dass der Orden hier ist. Er denkt, sie warten nur auf den rechten Moment, um zuzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80213] = { id = 80213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiliges Feuer in Bummelgau", description = "Ich bin mir sicher, dass hier immer noch Ordensleute herumschleichen. Vielleicht tragen sie Botschaften bei sich, genau wie die Hinweise, die Ihr in Freyholtz gefunden habt. \n\nWir werden es gemeinsam herausfinden.\n\nHier, nehmt diese Räucherwerkkugeln. Sie sehen aus wie kleine Räuchergefäße, aber ich habe sie mit der Heiligen Flamme verzaubert.\n\nWerft einfach eine hin und Ihr kriegt einen großen Knall mit einem grellen Blitz! Das sollte reichen, um jeden zu betäuben, der herumschleicht.\n\nAber werft bloß keine auf mich, verstanden?", sourceObjective = "Benutzt die Feuerblitzräucherwerkkugeln, um die Truppen des Ordens der Nacht in Bummelgau aufzuspüren, zu eliminieren und nach Hinweisen zu durchsuchen.", progress = "Na schön, ich gebe zu, das kleine Kieselchen ist ziemlich nützlich. Er weiß mehr über die Irdenen und die Oberfläche, als ich je wissen werde.\n\nWie auch immer, habt Ihr etwas gefunden?", completion = "\"Neue Freunde\", wie?\n\nIch bin wohl nicht der Einzige...\n\n<Kaerter erstarrt, als ihm bewusst wird, was er gerade gesagt hat, und zeigt plötzlich mit dem Finger auf Euch.>\n\nIhr habt nichts gehört, ist das klar?", sourceObjectiveStatus = "unverified-source-field" }
quests[80214] = { id = 80214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötungswerk am Sägewerk", description = "Mal sehen, ob ich das recht verstehe. Die Schiffsbauerin kommt mit einem Gefolge hierher, um Holz für die Luftschiffe zu besorgen.\n\nAber die Schiffsbauerin gehört eigentlich zum Orden der Nacht, genau wie die meisten ihrer Truppe. Also ermorden sie die loyalen Arathi, entführen Irdene und zwingen sie dazu, das Sägewerk hier oben zu betreiben.\n\nUnd jetzt müssen wir uns um den Orden UND ihre neuen Freunde kümmern, wer auch immer sie sein mögen?\n\n<Kaerter flucht und schüttelt den Kopf.>\n\nKommt, wir gehen zum Sägewerk. Wir müssen eine Menge Bösewichte töten, und die Zeit drängt.", sourceObjective = "Trefft Lampenanzünder Kaerter vor der Skolzgalmühle.", completion = "Neruber. Jede Menge Neruber.\n\nBeim Licht von Beledar, ich hasse Neruber.", sourceObjectiveStatus = "unverified-source-field" }
quests[80215] = { id = 80215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irdene Befreiung", description = "Es macht mir zwar Spaß, das Schwarzblut aus den Nerubern zu prügeln, aber zuerst müssen wir die irdenen Gefangenen retten.\n\nIch habe gesehen, dass sie von Arathi-Kugelfesseln gehalten werden. Jemand wie Ihr sollte sie ziemlich schnell zerschlagen können. Macht einfach das, was Ihr immer macht!\n\nOh, und wir sollten uns aufteilen, um ein größeres Gebiet abzudecken. Klar, Leif wird rummosern... aber er mosert sowieso immer rum.", sourceObjective = "Befreit 8 verschleppte Holzfäller.", progress = "Los, wir haben keine Zeit zu verlieren!", completion = "Gute Arbeit. Ich werde die wenigen, die ich retten konnte, in Sicherheit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80216] = { id = 80216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgen im Wald", description = "Die Neruber scheinen mit den Arathi im Bunde zu stehen. Viele von ihnen bewachen die Mühle, und ich bin sicher, dass es mehr sind, als wir sehen können.\n\nWir dürfen nicht zulassen, dass eine so große feindliche Streitmacht ungehindert bei Bummelgau aktiv ist.\n\nDie Neruber haben vor nicht allzu langer Zeit Dornogal angegriffen und große Teile davon zerstört. Die Arathi des Ordens der Nacht entführen und versklaven unser Volk.\n\nWir müssen möglichst viele von ihnen ausschalten - am besten alle.", sourceObjective = "Bezwingt Schattenseidenstreitkräfte an der Skolzgalmühle.", completion = "Das dürfte ihr Vorhaben stören. Hoffen wir, dass es vorerst reicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[80217] = { id = 80217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lampe für die Schiffsbauerin anzünden", description = "Wo ist Kaerter jetzt? Ist er wieder allein losgezogen?\n\n<Leif seufzt.>\n\nWir haben die Irdenen gerettet und viele feindliche Kräfte eliminiert, aber unsere Aufgabe ist noch nicht beendet.\n\nKurz vor Eurer Ankunft haben wir eine Gruppe Arathi gesichtet, die diesen Hügel hinaufgingen. Eine von ihnen war die Schiffsbauerin der Arathi.\n\nSie ist die Anführerin hier. Ihr Verlust wird ihren Bemühungen, das Sägewerk zu nutzen, einen ordentlichen Dämpfer verpassen.\n\nLauft den Hügel hinauf und findet sie, bevor sie fliehen kann.", sourceObjective = "Stellt die Schiffsbauerin der Arathi.", completion = "Kaerter ist verwundet. Er kann erst wieder effizient kämpfen, wenn er geheilt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[80218] = { id = 80218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfug im Seidenwald", description = "Der Orden transportiert das Holz über die Neruber. Leif sagte, er habe gesehen, wie die Schiffsbauerin die Höhle verließ und zum Strand hinunterging.\n\nDer nerubische Tunnel muss dort unten sein. Ihr müsst den flammenverlassenen Durchgang versiegeln.\n\nWährend ich mich dort herumschlich, bemerkte ich, dass der Orden explosive Fässer mitgebracht hat. Findet ein paar und sprengt damit den Tunnel.\n\nMacht Euch auf den Weg, {name}. Ich folge Euch auf den Fersen.", sourceObjective = "Sammelt Seidenwald-Sprengstofffässer und zerstört dann den Tunnel der Neruber in der Seidenwaldgrotte.", progress = "Habt Ihr den Tunnel beseitigt?", completion = "Feine Sache, {name}. Das sollte ihre Pläne vereiteln!\n\nOhne diesen Tunnel können sie das Holz nicht mehr nach Heilsturz schaffen. Damit ist das Sägewerk für sie nutzlos.\n\nPuh! Orden aufgehalten, Irdene gerettet, Neruber getötet. Klingt für mich nach guter Arbeit!\n\nIch weiß ja nicht, wie es Euch geht, aber ich könnte jetzt etwas Urlaub vertragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80219] = { id = 80219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dornogaldrift", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80220] = { id = 80220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmpostenstudie", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80221] = { id = 80221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beckenbypass", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
