quests[80236] = { id = 80236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzgrubenecken- Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80237] = { id = 80237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdwerkeweberei", description = "Auf der Strecke erwarten Euch gefährliche Flugmanöver! Eine todesmutige Verfolgungsjagd über einer albtraumhaften Magmalandschaft!\n\nWenn Ihr Euch der Herausforderung stellen wollt, durchfliegt die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80238] = { id = 80238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallende-Tiefen-Spektakel", description = "Also gut, ziehen wir los! \n\nSolange klar ist, wo oben und wo unten ist, sollte das hier kein Problem sein.\n\nNun, da wir das geklärt haben, müsst Ihr nur noch die Kontrollpunktringe durchfliegen, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80239] = { id = 80239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zirpendes Zusammentreffen", description = "Ich biete Euch eine Flugreise mit hervorragender Aussicht an. Ihr werdet unzählige schnatternde Kreaturen in einer ruhigen unterirdischen Wildnislandschaft sehen. \n\nWisst Ihr, was mehr Spaß macht? Ein Rennen! Durchfliegt einfach die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80240] = { id = 80240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kataraktflussfahrt", description = "Die malerische Aussicht auf den Fluss und die majestätischen Wasserfälle machen dieses Rennen in der Luft zu einem Vergnügen! \n\nDurchfliegt die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80242] = { id = 80242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taellochtrick", description = "Lasst Euch von der düsteren Gegend nicht ablenken.\n\nDie Bergbaustadt hat sich zwar verändert, aber die Aussicht ist spektakulär! \n\nWenn Ihr Nerven wie Drahtseile habt, durchfliegt die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80243] = { id = 80243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chancenspitzenchance", description = "Der südliche Teil der Schallenden Tiefen sieht ein wenig anders aus als der nördliche.\n\nOst oder West, Nord oder Süd, das Rennen erfordert immer noch schnelle Reflexe und Mut!\n\nNachdem Ihr einen kleinen Sprung in den Himmel gemacht habt, durchfliegt die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80244] = { id = 80244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdwerkeweberei - Fortgeschritten", description = "Die Irdenen unter uns arbeiten unermüdlich an den gleichen, sich wiederholenden Aufgaben, Tag für Tag.\n\nIhr hingegen riskiert Euer Leben, indem Ihr in waghalsigen Luftrennen über geschmolzenes Magma fliegt!\n\nWenn Ihr das Rennen wiederholen wollt, durchfliegt einfach die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80245] = { id = 80245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallende-Tiefen-Spektakel - Fortgeschritten", description = "Beim nächsten Rennen werdet Ihr Euren Augen kaum trauen. Die grünen Landschaften! Die hoch aufragenden Felsspitzen! Die sanften Brisen!\n\nDurchfliegt einfach die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80246] = { id = 80246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zirpendes Zusammentreffen - Fortgeschritten", description = "Habt Ihr das schon einmal gemacht? Habt Ihr die herrliche Tierwelt gesehen? Die tosenden Flüsse? Die herabstürzenden Wasserfälle?\n\nOh, Ihr wollt einfach nur rasen? Okay, das ist ganz einfach. Durchfliegt einfach die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80247] = { id = 80247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kataraktflussfahrt - Fortgeschritten", description = "Wenn Ihr Lust auf ein schwierigeres Rennen habt, versucht, schneller ins Ziel zu kommen ... und verbringt weniger Zeit damit, Euch die Landschaft anzusehen! \n\nFliegt einfach durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80248] = { id = 80248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taellochtrick - Fortgeschritten", description = "Schaut, wie sie da unten arbeiten! Ob es ihnen Spaß macht, manchmal den Rennen zuzusehen?\n\nNun denn, es spielt keine Rolle. So oder so, Ihr werdet durch die Kontrollpunktringe fliegen, die die Strecke markieren. Ich wünsche Euch viel Spaß!", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80249] = { id = 80249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chancenspitzenchance - Fortgeschritten", description = "Hey, ich habe ein Flugblatt gefunden! Da steht:\n\n\"Umschlängelt hoch aufragende Felsspitzen, taucht in versunkene Abgründe und durchfliegt das letzte Stück bis zur Ziellinie!\"\n\nIch bin sicher, Ihr wisst, was das wirklich bedeutet: Durchfliegt die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80250] = { id = 80250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdwerkeweberei - Umgekehrt", description = "In der Erdwerkeweberei gibt es Magma... und zwar jede Menge davon! Versucht, nicht daran zu denken, dass Ihr beim Fallen in einem brodelnden Alptraum enden könntet.\n\nKonzentriert Euch stattdessen darauf, die Kontrollpunktringe zu durchfliegen, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80251] = { id = 80251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schallende-Tiefen-Spektakel - Umgekehrt", description = "Habt Ihr Kopfschmerzen? Ich schon. Ich bin ein bisschen durcheinander gekommen, als ich durch die umgekehrte Version dieser Strecke geflogen bin.\n\nDas wird Euch nicht passieren, oder? Nein, natürlich nicht! Durchfliegt einfach die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80252] = { id = 80252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zirpendes Zusammentreffen - Umgekehrt", description = "Genießt die hervorragende Aussicht... UMGEKEHRT! Achtet dabei nur auf die Felsspitzen auf Eurem Weg.\n\nAußerdem müsst Ihr durch die Kontrollpunktringe fliegen, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80253] = { id = 80253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kataraktflussfahrt - Umgekehrt", description = "Klar, Ihr kommt schnell ins Ziel, aber könnt Ihr das auch... rückwärts? Nicht rückwärts fliegen. Ich meine, die Strecke rückwärts! \n\nIhr fliegt trotzdem durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80254] = { id = 80254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taellochtrick - Umgekehrt", description = "Maschinenflüsterer müssen arbeiten. Drachenreiter müssen rennen! Auch wenn ihre Arbeitseinheiten uns noch so sehr bitten, sie nicht weiter abzulenken!\n\nIhr müsst nur durch die Kontrollpunktringe fliegen, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80255] = { id = 80255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chancenspitzenchance - Umgekehrt", description = "Ich kenne diese Strecke so gut, dass ich sie vermutlich sogar rückwärts fliegen könnte. Hey, das könnt Ihr sicher auch!\n\nAber, dass Ihr mir nicht vom Weg abkommt. Fliegt einfach durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80256] = { id = 80256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunelles gute Güte", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[80257] = { id = 80257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenirs Traversale", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
