quests[80295] = { id = 80295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felsen, Wasser und Elementarfutter" }
quests[80310] = { id = 80310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Garnison der Untergehenden Sonne", description = "Vielleicht könnt Ihr ja Anji in der Garnison der Untergehenden Sonne westlich von hier aufsuchen? Sie ist damit beauftragt, die Pandarenrekruten auszubilden. Und Ihr könntet ihnen wohl auch noch ein oder zwei Dinge beibringen.", sourceObjective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne.", completion = "Mit Euch kann man arbeiten. Dann zeigen wir diesen Auszubildenden mal, wie ein echter {class} kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[80311] = { id = 80311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orden der Wolkenschlange", description = "Auf Schildkröten reiten ist das Beste!\n\nAber auf Wolkenschlangen reiten ist noch besser!\n\nEs gibt einige Leute im Arboretum, die Wolkenschlangen reiten und es Euch beibringen können!", sourceObjective = "Sprecht mit der Ältesten Anli im Arboretum.", completion = "Ah, noch ein Schüler der Lüfte. Willkommen im Arboretum.", sourceObjectiveStatus = "unverified-source-field" }
quests[80312] = { id = 80312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keuchende Bitte", description = "<Ein erbärmlich aussehender Fisch, den Ihr im Leichnam eines Kobyss gefunden habt, zappelt in Eurer Hand und schnappt nach Luft. Seine glänzenden Augen zucken und plötzlich vernehmt Ihr im Kopf eine atemlose Stimme.>\n\nWasser. Bringt mich ins Wasser. Weg von den grässlichen Kobyss. Weg vom Himmel.", sourceObjective = "Setzt den seltsamen Fisch in sichere Gewässer nahe des Kobysslagers am Sonnenlosen Strand.", completion = "<Der Fisch saugt gierig das Salzwasser auf, um seinen Atem wiederzufinden. Dann sieht er Euch mit intelligenten Augen an.>\n\nIch verdanke Euch mein Leben. Der Schatten dieser Felsen passt mir gut für die Arbeit, die zu tun ist.\n\nErlaubt mir, mich für Euren selbstlosen Dienst erkenntlich zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80313] = { id = 80313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezeitenglücksbringer", description = "<Der Fisch spricht mit Euch, ohne dass sich seine Lippen bewegen. Ihr hört seine Stimme nur in Eurem Kopf.>\n\nIhr habt sicher bemerkt, dass Ihr Euren Sinnen nicht trauen könnt, wenn Ihr es mit den Kobyss zu tun habt. Eine fürchterliche Macht, nicht wahr? Somit ist es nur gerecht, wenn Ihr ihnen zeigt, dass nicht nur sie diese Macht einsetzen können.\n\nIch werde Euch zeigen, wie Ihr ein Werkzeug herstellt, um sie anzulocken und zu vernichten. Ihr werdet feststellen, dass die Unholde Splitter aus der Tiefe bei sich tragen. Bringt sie mir.", sourceObjective = "Sammelt 12 Sonnenlose Splitter von den Kobyss am Sonnenlosen Strand.", progress = "Bringt mir die Materialien. Erst dann können wir fortfahren.", completion = "Glitzernde Abyssalsplitter und Korallenstränge, verbunden mit Worten der Macht und um den Hals getragen. Ich werde Euch zeigen, wie Ihr die Sinne Eurer Feinde überlistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[80314] = { id = 80314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmen aus der Tiefe", description = "Die Sinne dieser Kobyss zu täuschen, ist nur das Eine. Ihr müsst auch wissen, womit Ihr sie ergötzt. Ihnen läuft das Wasser im Munde zusammen, wenn sie nur daran denken, Euresgleichen zu verzehren. Aber es sind die Stimmen der Tiefe, die sie in ihren Bann ziehen, damit sie unvorsichtig werden. Und genau in dem Moment schlagt Ihr zu.\n\nSeht Euch in ihren Schreinen um, um zu lernen, was diesem Abschaum heilig ist. Bringt in Erfahrung, wie sie die donnernden Wahrheiten der Tiefe verdreht haben.", sourceObjective = "Untersucht drei Ritualstätten, um mehr über die Kobyss zu erfahren.", progress = "Was habt Ihr erfahren?", completion = "Ihr versteht jetzt, was die Kobyss begehren. Es ist Zeit, dieses dunkle Wissen einzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80315] = { id = 80315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köder für die Kobyss", description = "Es ist vollbracht. Nehmt diesen Gezeitenglücksbringer, tarnt Eure Gestalt in der Dunkelheit der See und löscht sie aus. Ihre stärksten Krieger versammeln sich auf der mittleren Insel, um ihre grausamen Pläne gegen Eure Art auszuhecken. Dank des Köders durchschauen sie nicht, wer Ihr seid. Nutzt diesen Vorteil, um ihnen ein Ende zu setzen.\n\nAber Ihr müsst eines begreifen, was die Kobyss nicht verstehen: Ihr borgt diese Macht nur. Sie gehört dem Meer.", sourceObjective = "Ködert und ermordet Kiemenschnitzer und seine Kobyssgezeitenmarschalls auf der Insel vor dem Sonnenlosen Strand.", progress = "Isoliert sie. Vernichtet sie.", completion = "Damit wurde Ihnen eine Lektion erteilt. Sie werden es sich nun zweimal überlegen, bevor sie meinesgleichen noch mal als Beute betrachten.\n\nIhr tötet gut, Landgänger. Aber die Macht der Tiefe verlangt, dass Ihr sie zurückgebt. Unsere gemeinsame Zeit nähert sich ihrem Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[80316] = { id = 80316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr ins Meer", description = "Ich bin noch immer geschwächt von meinem unfreiwilligen Ausflug ans sengende Licht der Oberfläche. Ich bitte Euch, dass Ihr mich in tiefere Gewässer bringt, fern von diesen Kobyss, damit ich zu meinem Volk zurückkehren kann.", sourceObjective = "Bringt den seltsamen Fisch in tiefere Gewässer.", completion = "<Der Fisch stößt einen trällernden Ruf aus. Er trägt sein Lied in die Tiefen des Ozeans.>\n\nIch hatte schon mit einem schmählichen Ende für meine Torheit durch die gierigen Hände der Kobyss gerechnet. Ich hätte mir nie ausmalen können, dass ausgerechnet ein Landgänger zu meinem Retter werden würde. Ich werde Euch nie vergessen. Nun, genug der falschen Fassade. Mein Volk erwartet mich.\n\n<Die Form des Fisches beginnt sich zu wandeln und vor Euren Augen aufzulösen. Ihr erkennt, dass seine Fischgestalt bloß eine weitere Illusion war.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80320] = { id = 80320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Klaxxi", progress = "Steht uns bei, Erwecker, damit das Mantisreich weiter wächst.", completion = "Ja, gut." }
quests[80321] = { id = 80321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abreise", description = "Am besten teilen wir uns hier auf. Ich bringe alle in Sicherheit und sorge dafür, dass sie evakuiert werden.\n\nIn der Zwischenzeit solltet Ihr Khadgar aufsuchen. Ich bin mir sicher, dass er Eure Hilfe gebrauchen kann.\n\nWeiter vorne findet Ihr einen weiteren Ausgang, der zurück zur Oberfläche führt.", sourceObjective = "Findet Khadgar an der Oberfläche.", completion = "<Das Portal flackert und windet sich, sodass man die andere Seite nicht sehen kann.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80323] = { id = 80323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konfrontation im Nebel" }
quests[80334] = { id = 80334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmetterte Spitzen", description = "Die Spitzen von Dalaran zerbröckeln, weil nichts ihre arkane Macht zurückhält.\n\nWenn wir das unkontrollierte Ausströmen ihrer Energien nicht unterbinden, könnte das unsere restlichen Truppen destabilisieren und vernichten.\n\nFindet Aethas! Er wird wissen, was zu tun ist.", sourceObjective = "Findet Aethas am Ruhigen Ufer.", completion = "Jaina lebt noch?\n\nDem Sonnenbrunnen sei Dank!\n\nDoch niemand von uns wird lange überleben, wenn wir die Energien der Spitzen nicht eindämmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[80349] = { id = 80349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit, zurückzukehren", description = "Ihr macht Euch jetzt besser auf den Weg. Das Portal sollte Euch ins Dorf zurück bringen.", sourceObjective = "Kehrt zu Moratari zurück.", completion = "Ausgezeichnet. Ich hoffe, das bringt unsere Forschung voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[80378] = { id = 80378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Licht der Dunkelheit", description = "Das Bild einer mit glorreicher Kraft brennenden lilafarbenen Kerze baut sich ungefragt in Eurem Geist auf, als Ihr den zerfallenden Unrat vor Euch betrachtet. Anschließend hallt ein fernes Flüstern in Eurem Verstand wider: \"Eine Kerze, sie zu knechten und in ihrer Helligkeit ewig zu binden.\"\n\nBringt dem Kerzenschmied Janky in Gundargaz genügend geronnenes Schwarzblut, um eine höchst unselige Kerze daraus zu fertigen.", sourceObjective = "Sammelt geronnenes Schwarzblut und bringt es dem Koboldkerzenschmied Janky in Gundargaz.", progress = "<Als Ihr Euch nähert, beginnt Janky zu zittern.>\n\nAh!", completion = "Oh... Janky normalerweise nix neue Kerze ablehnen, aber Ihr sicher?", sourceObjectiveStatus = "unverified-source-field" }
quests[80380] = { id = 80380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantel und Nadel", description = "Sobald Ihr den Umhang anlegt, wird es Euch möglich sein, an Gegnern Fäden wahrzunehmen.\n\nDer Umhang wird ganz von selbst diese Fäden absorbieren und so Eure Macht dauerhaft erhöhen.\n\nVersucht, einen Faden von den ewigen Verheerern in der Nähe zu sammeln.", sourceObjective = "Legt Euren Umhang des ewigen Potenzials an und sammelt einen Faden der Macht von einem ewigen Verheerer.", progress = "Ihr müsst dafür kein Schneider sein. Der Umhang wird die Fäden für Euch einweben.", completion = "Ihr werdet überall ähnlich Fäden finden, bei erledigten Gegnern bis hin zu geplünderten Schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80382] = { id = 80382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moralapostel", description = "<Dieser Arbeitsauftrag ist noch nicht erfüllt. Aliya Hügelpinne wäre bestimmt froh, wenn Ihr dabei helft, ihn abzuschließen.>", sourceObjective = "Sammelt 10 Eier vom Hügelpinnenhof und legt sie in diesen Korb.", progress = "Benachrichtigt Aliya, dass der Arbeitsauftrag abgeschlossen ist.", completion = "Habt vielen Dank! Seit Tante Gerta uns verlassen hat, fehlt es an allen Ecken und Enden. Jede Hilfe ist uns willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80384] = { id = 80384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paket mit Fassstempel", description = "<Eine unscheinbare Gestalt drückt Euch einen Zettel mit einem kleinen, zerknitterten Paket daran befestigt in die Hand und verschwindet geschwind in der Menge. Die Buchstaben auf dem Zettel wirken grob gekritzelt, wie mit einem in Tinte getauchten Dolch geschrieben.>\n\nHier ist Euer Teil der Beute.\n\nHabe die Kameraden ins Gasthaus geschickt.\n\n<Ihr schaut nach, ob noch etwas anderes auf dem Zettel steht, und findet unten am Rand das Bild eines Fasses.\n\nIhr schüttelt das Paket vorsichtig und hört das untrügliche Geräusch klimpernder Münzen.>", sourceObjective = "Bringt die Notiz mit Fassstempel zu Da'kash Grimjoch im Gerösteten Geißbock in Valdrakken.", completion = "Ihr habt ein Paket von Fasshaxe bekommen, was?\n\nIch weiß ja nicht, inwieweit Ihr in unsere Geschäfte involviert seid, aber es steht mir nicht zu, den Kapitän infrage zu stellen.\n\nSeht Euch den Kram hier an, den ich geplündert habe. Ich gebe Euch ein paar gute Sachen für diese Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80385] = { id = 80385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Hurra: Dracheninseln", description = "Ihr seid unter unseren Verbündeten sehr beliebt geworden, {name}!\n\nDie Tuskarr von Iskaara im Süden brauchen Eure Hilfe bei ihrem gemeinschaftlichen Festmahl.\n\nIm Westen haben die Maruuk Eure Hilfe bei ihren Jagden angefordert.\n\nDie Obsidianausgestoßenen im Norden bitten um Eure Unterstützung bei der Rückeroberung der Drachenfluchfestung.\n\nKlingt, als hättet Ihr einen langen Tag vor Euch. Viel Glück.", sourceObjective = "Helft den Tuskarr bei ihrem gemeinschaftlichen Festmahl, den Maruuk bei ihrer Jagd und unterstützt die Rückeroberung der Drachenfluchfestung.", progress = "Wir haben Glück, Euch auf unserer Seite zu haben, {name}.", completion = "Dank Eurer Bemühungen sind die Dracheninseln sicherer.\n\nNehmt bitte dieses Zeichen unserer Anerkennung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[80386] = { id = 80386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Hurra: Zaralekhöhle und Zeitrisse", description = "Unsere Verbündeten haben einmal mehr um Eure Unterstützung gebeten, {name}.\n\nIn der Zaralekhöhle braucht die Drachenschuppenexpedition Euren Schutz für ihre Forscher.\n\nWir sind auch besorgt wegen der Invasionen der Zaqali auf den Ebenen von Ohn'ahra und im Azurblauen Gebirge.\n\nUnd der bronzene Drachenschwarm hat darum gebeten, dass Ihr ihnen bei den Zeitanomalien östlich von Valdrakken helft.\n\nBeeilung, {name}, die Zeit drängt.", sourceObjective = "Beschützt die Forscher unter Feuer, plündert eine gesicherte Lieferung aus einem Durchdringungslager und helft Soridormi dabei, einen Zeitriss zu schließen.", completion = "Ich habe gute Neuigkeiten von jenen erhalten, denen Ihr geholfen habt, {name}.\n\nNehmt bitte dieses Geschenk an.", sourceObjectiveStatus = "unverified-source-field" }
quests[80388] = { id = 80388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Hurra: Smaragdgrüner Traum", description = "Die Druiden rufen um Hilfe!\n\nEnergie aus dem Smaragdgrünen Traum breitet sich über die Dracheninseln aus. Helft ihnen bitte, sie zu untersuchen.\n\nSie haben Euch außerdem gebeten, in den Smaragdgrünen Traum zu reisen und Fichtenkrone bei einer Superblüte zu helfen.\n\nEinige der Druiden bitten Euch zusätzlich darum, Traumsaat im Smaragdgrünen Traum zu pflanzen.\n\nHelft ihnen bitte, {name}.", sourceObjective = "Sammelt hundert Teile Traumsprungvereinigung auf den Dracheninseln, helft Fichtenkrone bei der Superblüte, pflanzt 3 Traumsaaten beliebiger Qualität im Smaragdgrünen Traum. Traumsaat kann bei den meisten Aktivitäten im Smaragdgrünen Traum verdient werden.", completion = "Die Arbeit, die Ihr im Smaragdgrünen Traum geleistet habt, wird Azeroth sicher helfen, zu heilen.\n\nNehmt bitte dieses bescheidene Geschenk und unsere Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[80389] = { id = 80389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Hurra" }
quests[80392] = { id = 80392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verwalterin von Brunwins Terrasse", description = "Seid gegrüßt, Fremdling. Ihr müsst <der Problemlöser/die Problemlöserin> sein, <der/die> in aller Munde ist! Ich bin Verwalterin Batzvara. Ich kümmere mich um Irdene, die in Stasis übergegangen sind, wie unser Freund hier.\n\nIch patrouilliere oft auf Brunwins Terrasse, um die Irdenen mit einem Becher Glutbräu zu ehren. In letzter Zeit ist jedoch eine einheimische Maulwurfsart auf mich aufmerksam geworden. Sie haben ein Gespür für Süßigkeiten und gierige Krallen für alles andere.\n\nIhr seht aus, als wüsstet Ihr Euch zu verteidigen. Würdet Ihr mich begleiten, um jenen, die in Stasis gefallen sind, Respekt zu erweisen?", sourceObjective = "Bringt 6 inaktiven Irdenen Glutbräu dar und tötet 10 Süßschnüffler.", completion = "Euch gehört meine Dankbarkeit. Euer Ruf als verlässlicher Verbündeter ist wohlverdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[80394] = { id = 80394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beifahrer" }
quests[80395] = { id = 80395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Ausgrabung" }
quests[80397] = { id = 80397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süßigkeitensucher", description = "Das Glutbräu der Irdenen ist ein mächtiges Getränk. Es ist gefährlich für alle, die nicht so robust sind wie wir. Schlimmer jedoch ist, dass sein süßer Geschmack eine bösartige Maulwurfsart anlockt. Sie tun alles, um es in ihre Krallen zu bekommen!\n\nWenn ich die Irdenen auf Brunwins Terrasse mit dem süßen Kelch ehre, wird mein kräftiges Gebräu ihre Aufmerksamkeit erregen. Wenn Ihr in meiner Nähe seid, haltet die Augen nach ihnen offen, um sie zur Strecke zu bringen.", sourceObjective = "Tötet 12 Süßschnüffler.", sourceObjectiveStatus = "unverified-source-field" }
quests[80399] = { id = 80399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essen gegen Vergessen", description = "Wir haben diese Gefangenen bei der Flucht aus einer nahe gelegenen nerubischen Militärbasis aufgegriffen.\n\nDie Umstände ihrer Flucht sind selbst ihnen... unklar. Es war, als habe jemand anderes einen Fluchtweg für sie geöffnet.\n\nSie brauchen Ruhe, aber wir müssen herausfinden, was dort drinnen passiert ist.\n\nErst müssen sie etwas essen. Vielleicht erinnern sie sich, wenn sie wieder zu Kräften kommen.", sourceObjective = "Verteilt 3 Arathirationen.", progress = "Wir haben es geschafft, einen einfachen Eintopf zuzubereiten. Nicht das leckerste Festmahl, aber gewiss besser als das, was sie im Spinnengefängnis essen mussten.", completion = "Sie haben so viel durchgemacht. Und das als Zivilisten. Es sind nicht einmal Soldaten. Für so etwas haben sie sich nicht gemeldet. Und doch endeten sie als Kriegsgefangene.\n\nWenn uns irgendetwas in dieser nerubischen Basis einen Vorteil verschaffen kann, müssen wir das ausnutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80401] = { id = 80401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Schwamm", description = "Willkommen an den Schimmernebelfällen, <standhafter Kollege/standhafte Kollegin>! Hier ist es immer klamm... ein florierendes Paradies für alle grünen und lebendigen Dinge. Bedauerlicherweise ist es auch das perfekte Klima, um für Moosbewuchs an meinen inaktiven Irdenenfreunden zu sorgen.\n\nWir werden zur Entfernung der Moose einige Vorräte besorgen müssen. Zunächst brauchen wir einen Schwamm, um ihre Oberflächen zu waschen. Er muss weich genug sein, sie nicht zu beschädigen, aber hart genug, um gegen die raue Steinhaut eines Irdenen anzukommen.\n\nDie Kappen der Peitschenpilze unter uns sind wie dafür gemacht!", sourceObjective = "Sammelt eine perfekte Peitschenpilzkappe.", progress = "Aus diesen Peitschenpilzkappen kann man hervorragende Schwämme machen!", completion = "Auftrag abgeschlossen! Der ist perfekt! Und Eure Leistung ist selbstverständlich optimal.", sourceObjectiveStatus = "unverified-source-field" }
quests[80402] = { id = 80402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Eimern und Blüten", description = "Zwischen den kriechenden Peitschenpilzen wächst eine orangefarbene Blume. Wenn man ihre Blüten mit Wasser mischt, entsteht ein ätzendes Lösungsmittel, mit dem sich hervorragend Moos von Irdenenhaut entfernen lässt.\n\nAls ich das letzte Mal hier war, habe ich den Eimer, in dem ich das Lösungsmittel anrühre, neben diesem Irdenen stehen lassen. Irgendetwas scheint sich damit davongemacht zu haben.\n\nKann ich Euch mit der Wiederbeschaffung betrauen? Ich werde hier warten. Die Maulwürfe von der Terrasse haben mir für einen Tag genug Aufregung beschert.", sourceObjective = "Sammelt 8 Ätzblüten und findet den vermissten Eimer.", progress = "Der Säuregehalt der Pflanzen ist stark genug, um das Moos zu entfernen, aber auch mild genug, dass die Irdenen dabei nicht beschädigt werden. Außerdem hat das Gemisch einen angenehmen Geruch an sich. Er erinnert an Schwefel.", completion = "Ah, ich rieche den Schwefel bis hierhin! Vielen Dank, dass Ihr den Eimer und die Blüten besorgt habt.\n\nEs mag nicht jedermanns Geschmack sein, aber für mich gehts nichts über leicht angesengtes Magma in einer Feuerschale, vor allem, wenn es schon so schwefelreich duftet.\n\nWas? Ihr habt es noch nie probiert? Nun, jeder wie er mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[80404] = { id = 80404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosige Irdene", description = "Herausragende Arbeit beim Sammeln der Sachen. Ich habe die Lösung für Euch zusammengemischt.\n\nJetzt müssen wir nur noch unsere moosbedeckten Freunde da unten saubermachen.", sourceObjective = "Kümmert Euch um 4 moosige Irdene.", progress = "Machen wir unsere Freunde sauber.", completion = "Schon viel besser! Irdene sollten harter Stein und nicht weicher Flaum sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[80405] = { id = 80405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu stylisch", description = "Das ist Ausgazur. Seine Hand ist gewöhnlicherweise mit einer Auswahl seiner liebsten Edelsteine gefüllt. Wir wissen nicht wirklich, wie es ist, wenn wir in Stasis verfallen, aber er wollte seine letzten Momente damit verbringen, die natürliche Schönheit Azeroths und ihrer Schätze einzunehmen.\n\nIch fürchte, dass etwas oder jemand sich mit den Juwelen davongestohlen hat, die er normalerweise in der Hand hält. Sehen wir uns um. Schaut, ob Ihr nicht irgendwelche Hinweise darauf finden könnt, wohin sie sind.", sourceObjective = "Untersucht Ausgazur auf Hinweise.", progress = "Ausgazur wird mir nie verzeihen, wenn seine Edelsteine verloren gehen. Das ist überaus ärgerlich. Wer würde von einem Irdenen in Stasis stehlen?", completion = "Kobolde haben sich mit seinen Edelsteinen aus dem Staub gemacht? Das ist inakzeptabel! Wir müssen die restlichen Juwelen von Ausgazur beschaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[80406] = { id = 80406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgazurs Edelsteine suchen", description = "Es waren also Kobolde, die sich mit Ausgazurs Edelsteinen aus dem Staub gemacht haben. Mir war nicht bewusst, dass die Wasserwerke angegriffen werden. Genau zur rechten Zeit für die Verteidiger weiter unten!\n\nWir müssen diese Juwelen zurückholen! Ich bleibe hier und bewache die verbleibenden Edelsteine, würde Euch jedoch dringend darum bitten, Euch um eine wichtige Aufgabe zu kümmern: Begebt Euch nach unten zu den Wasserwerken und bergt den Rest.", sourceObjective = "Beschafft 4 von Ausgazurs Edelsteinen.", progress = "Wir müssen den Rest von Ausgazurs Edelsteinen finden! Das hat höchste Priorität!", completion = "Ausgezeichnete Arbeit! Auch wenn sie nicht viel Geld wert sind, bedeuteten diese Edelsteine Ausgazur sehr viel. Ich bin froh, dass er nicht länger von ihnen getrennt sein muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[80407] = { id = 80407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flackerdocht die Edelsteingrabscherin", description = "Der Kobold hat Flackerdocht erwähnt, nicht wahr? Klingt, als wäre sie die treibende Kraft hinter diesen Edelsteindieben. Ich verwette meinen Bart, dass sie sich Ausgazurs letzten Edelstein geschnappt hat!\n\nSucht in den Wasserwerken nach ihr und seht nach, ob sie diesen letzten Edelstein hat. Möglicherweise steckt sie auch hinter dem gegenwärtigen Angriff. Wenn Ihr sie ausschaltet, wird das den Verteidigern helfen.", sourceObjective = "Tötet Flackerdocht.", progress = "Flackerdocht wird mit dieser Dieberei nicht einfach so davonkommen!", completion = "Ihr habt es geschafft! Ihr habt den letzten Edelstein gefunden! Ich bin froh, dass Flackerdocht nicht mehr hinter Ausgazurs Edelsteinen her ist.\n\nDas hier war sein Lieblingsedelstein. Anders als die anderen ist er nicht facettiert. Ausgazur konnte auch in mangelhaften und beschädigten Dingen stets Schönheit finden. Er hat ihn mir gezeigt und seine Farbe und sein Potenzial bewundert. Er wollte nie, dass er poliert wird.\n\n<Sie ist einen Moment lang still und blickt anschließend zu dem grauen Irdenen neben ihr.>\n\nAh, Ausgazur. Du hast dich auch nie darum gekümmert, wie ich aussehe. Du sahst immer das Potenzial in mir. Ich vermisse dich, alter Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[80408] = { id = 80408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmernebelfälle", description = "Westlich von Gundargaz gibt es einen weiteren grünen Ort... einen bezaubernden Bereich mit Wasserfällen und weiteren Terrassen. Laut Plan ist das mein nächstes Ziel. Ich würde mich freuen, wenn Ihr mir auch dort helfen könntet, mit der ansässigen Tierwelt zurechtzukommen.\n\nWenn Eure anderen Pflichten es erlauben, dann trefft mich dort.", sourceObjective = "Trefft Batzvara an den Schimmernebelfällen.", completion = "Ihr habt es geschafft! Machen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[80409] = { id = 80409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polarisiert" }
quests[80412] = { id = 80412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf gegen die Dunkelheit" }
quests[80426] = { id = 80426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Shado-Pan", progress = "Die Shado-Pan wären Euch dankbar, wenn Ihr uns beistehen würdet.", completion = "Ihr seid nicht nur geschickt im Kampf, sondern auch noch großzügig! Habt Dank, {name}." }
quests[80427] = { id = 80427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft dem Goldenen Lotus", progress = "Seid Ihr gekommen, um uns zu helfen?", completion = "Wunderbar. Setzt Eure Ausbildung fort, dann sind wir auf alles vorbereitet!" }
quests[80429] = { id = 80429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Himmlischen Erhabenen", progress = "Das Sha zwingt uns dazu, darüber nachzudenken, wofür es sich zu kämpfen lohnt. Was seid Ihr bereit, für die Zukunft Pandarias zu opfern?", completion = "Ihr seid tapfer und ehrenhaft." }
quests[80430] = { id = 80430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Himmlischen Erhabenen", progress = "Habt Ihr Opfergaben für den mächtigen Schwarzen Ochsen dabei?", completion = "Seid stolz und kämpft zügig." }
quests[80431] = { id = 80431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Himmlischen Erhabenen", progress = "Seid gegrüßt, Herausforderer. Ich werde Eure Gaben in meinem Tempel entgegennehmen.", completion = "Kämpft mit Kraft und Ehre." }
quests[80433] = { id = 80433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Himmlischen Erhabenen", progress = "Üben heißt, sich selbst zu stärken. Geben heißt, die Gemeinschaft zu stärken.", completion = "Ihr bringt uns Ehre." }
quests[80434] = { id = 80434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefen", description = "Also, vorwärts und abwärts. Wir sollten Sprecherin Brinthe wohl folgen und uns selbst ein Bild davon machen, was die Neruber ihrem Zuhause angetan haben.\n\nMagni, Dagran und ich werden bald nachkommen. Wärt Ihr so nett, voranzugehen und dafür zu sorgen, dass uns dort ein herzlicher Empfang erwartet?", sourceObjective = "Sucht nach Sprecherin Brinthe am Grunde des Kernwegs.", completion = "Bei den Titanen! Die Neruber haben unserer Station ja wirklich zugesetzt... aber ich kann keinen von den spinnenartigen Teufeln sehen. Nur Maschinenflüsterer in Not...", sourceObjectiveStatus = "unverified-source-field" }
quests[80438] = { id = 80438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft der Horde", progress = "Lok'tar, {name}. Welch Hilfe bringt Ihr uns?", completion = "Für die Horde!" }
quests[80439] = { id = 80439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft der Allianz", progress = "König Varian verlangt nach Eurer Unterstützung, {name}. Habt Ihr uns Vorräte gebracht?", completion = "Ein Soldat ist immer im Dienst." }
quests[80441] = { id = 80441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft dem Orden der Wolkenschlange", progress = "Die Wolkenschlangen benötigen günstige Winde. Habt Ihr das Glück im Schlepptau?", completion = "Ausgezeichnet. Mögen Euch die Winde auf Eurer Reise Euch wohlgesonnen sein." }
quests[80442] = { id = 80442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft dem Sonnenhäscheransturm", progress = "Meine Späher berichten von Feindaktivität. Habt Ihr Vorräte für unsere Truppen dabei?", completion = "Sehr gut. Wir werden sofort den Gegenangriff vorbereiten." }
quests[80443] = { id = 80443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft der Offensive der Kirin Tor", progress = "Ohne Blutvergießen kann es keinen Sieg geben. Seid Ihr hier, um uns zu helfen, {class}?", completion = "Das wird der Kriegskasse zugutekommen." }
quests[80444] = { id = 80444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Anglern", progress = "Hallo, mein Freund! Konntet Ihr in letzter Zeit ein paar Amulette an Land ziehen? Die Einheimischen behaupten, sie würden den Gewässern Glück bringen.", completion = "Tausendfachen Dank! Damit werden wir sicher einen großen Fang landen!" }
quests[80446] = { id = 80446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Gruppe", description = "Da ist mein Lieblingschampion!\n\nWenn Ihr ein Ziel für die Jagd sucht, ich kenne da einige Dungeons, die eine Erkundung wert sind.", sourceObjective = "Besiegt 3 Dungeonbosse.", progress = "Wie läuft die Dungeonerkundung?", completion = "Ich wusste, Ihr schafft das!", sourceObjectiveStatus = "unverified-source-field" }
quests[80447] = { id = 80447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach mehr", description = "Ihr haltet Euch für echt stark?\n\nDas glaube ich Euch, wenn Ihr eine echte Herausforderung annehmt.\n\nBesiegt die stärksten Gegner in Pandaria, dann sehen wir ja, wie stark Ihr wirklich seid.", sourceObjective = "Besiegt 2 Schlachtzugsbosse.", progress = "Die wahre Herausforderung ist, genug andere Schwächlinge zu finden, mit denen Ihr Euch zusammenschließen könnt.", completion = "Ich schätze, Ihr seid doch recht hart im Nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[80448] = { id = 80448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein frischer Wind", description = "Oh-oh, Schätzchen, ich werde nicht zulassen, dass Ihr den ganzen Tag in dunklen Dungeons verbringt, wo niemand Eure Ausrüstung bewundern kann!\n\nZieht Eure Ausgehkleidung an, dann bringen wir Euch in eine frischere Gegend!", sourceObjective = "Schließt ein Szenario ab.", progress = "Ihr würdet mich nie tot in einem Dungeon finden, nichts da. Ihr wisst, was da unten ist? Schlamm! Spinnweben! Leute mit viel zu großen Schulterpolstern.\n\nNein, mein Herr, ich bleibe genau hier, vielen Dank.", completion = "Ooh, Schätzchen, ich kann sehen, dass Ihr an einem spannenden Ort wart.\n\nIch will alles darüber wissen!", sourceObjectiveStatus = "unverified-source-field" }
quests[80456] = { id = 80456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kesser Arathi", description = "Ich hatte gehört, dass ein Arathi in der Stadt für Ärger sorgt. Klingt, als würde er sich mit den Friedensbewahrern anlegen.\n\nIhr habt schon mal mit den Arathi gearbeitet, nicht wahr? Vielleicht könnt Ihr die Wogen dort ein wenig glätten.", sourceObjective = "Sprecht mit Friedensbewahrer Leif in Dornogal.", completion = "Ja? Wie kann ich Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[80457] = { id = 80457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dienst der Königin" }
quests[80500] = { id = 80500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bronzebart-Familie", description = "<Moira holt tief Luft.>\n\nWir müssen Brann und meinen Sohn Dagran wissen lassen, was geschehen ist. Sie sind im Besucherzentrum von Dalaran.\n\nKönntet Ihr sie für mich herholen? Vater braucht jetzt seine Familie.", sourceObjective = "Begebt Euch zu Brann und Dagran im Besucherzentrum von Dalaran, um sie darüber zu informieren, was mit Magni geschehen ist.", progress = "Mein Sohn hat sich schon immer für die Wissenschaften interessiert. Da kommt er ganz nach seinem Vater...\n\nWir sind alle sehr stolz auf ihn.", completion = "Es ist gut, dass wir alle in einem Raum sind, auch wenn der Grund dafür so furchtbar ist. Mein Vater hat nicht wirklich... an Dagrans Leben teilgenommen. Aber ich habe vor, das zu ändern, darauf habt Ihr mein Wort.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[80502] = { id = 80502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weint nicht um mich, Azj-Kahet", description = "<Ihr findet eine zerknitterte Seite aus einem Tagebuch um einen kleinen Schlüssel gewickelt.>\n\nIch habe immer vermutet, dass Arax'ne Traditionalistin ist, aber ich hätte nicht gedacht, dass sie so weit gehen würde. Ich weiß nicht, wohin ich gehen werde, aber ich muss einfach von ihr wegkommen.\n\nFür den, der das findet, bedeutet es, das Schlimmste ist geschehen. Dieser Schlüssel öffnet eine Truhe, die alle meine weltlichen Besitztümer enthält. Sie gehören Euch.\n\nIch bitte Euch lediglich darum, Arax'ne zu töten, um mich zu rächen.", sourceObjective = "Rächt Klaskin und tötet Arax'ne auf dem Umbralbasar.", progress = "Der Schlüssel glänzt silbern im Licht von Azj-Kahet.", completion = "Der Inhalt dieser Truhe soll nun Euch gehören.\n\n- Klaskin", sourceObjectiveStatus = "unverified-source-field" }
quests[80508] = { id = 80508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung im Bau", description = "Ihr Freund der Kobolde, ja? Brauchen Hilfe. Schlimme Sachen passieren im Zirpenden Bau.\n\nMürrzahnbande Lager aufschlagen. Handlanger von Kerzenkönig wollen Krieg mit Irdenen.\n\nAllein wir sie nicht aufhalten. Trefft mich beim Lager.", sourceObjective = "Trefft Skrit in ihrem Lager im Zirpenden Bau.", completion = "Ihr hier. Gut. Viel zu tun. Viel zu beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80509] = { id = 80509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleimanzug", description = "Mürrzahnbande Euch nicht so ins Lager lassen. Ihr verkleiden müssen. Aussehen müssen wie Insekt. Dann wir reingehen.\n\nZuerst Wachs brauchen. Hier viel geben. Schleimbestien welches haben oder Ihr kratzen von Hüpfern.\n\nDann wir Wachs an Euch kleben. Insektenteile an Wachs kleben. Perfekte Verkleidung.", sourceObjective = "Sammelt 20 Exemplare klebriges Wachs von Wachsabströmen und wachsverderbten Springern.", progress = "Mit richtiger Verkleidung niemand wissen, dass Ihr kein Käfer.", completion = "Das alles. Bald Ihr seht aus wie Käfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[80510] = { id = 80510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung des Oberlaufs", description = "Mürrzahnbande so verschwenderisch! Lassen so viel Schott im Wasser. Schlecht für Wasser. Schlecht für Schrott. Geht aufräumen.", sourceObjective = "Entfernt 6 Exemplare Wachsschrott.", completion = "Viel besser. Sinnlos Schrott in Wasser verrotten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80511] = { id = 80511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lagerinspektion", description = "Jetzt wir bringen Euch zu Lager. Ihr seht, was Boss Schnurrpeitsche macht. Zieht Käferverkleidung an, wenn wir nah am Lager. Überlasst Reden mir.", sourceObjective = "Untersucht das Lager der Mürrzahnbande.", progress = "Lager darf nicht stehen bleiben. Zu viel zu verlieren für Kobold und Irdene.", completion = "Ihr seht, was Mürrzahnbande machen? Halten sogar Irdenen gefangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[80512] = { id = 80512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besser als die Besten", description = "Wenn Mürrzahnbande erfolgreich, dies nur erster Gefangener von vielen. Wir müssen befreien.\n\nEr Preis. Jeder Kobold hier will kämpfen gegen ihn. Müssen unseren Platz verdienen.\n\nIhr verprügelt starke Käfer, sie glauben, ich starke Trainerin. Dann sie lassen Euch in Ring.\n\nMöge bester Käfer gewinnen.", sourceObjective = "Besiegt die Käfertrainer.", progress = "Besiegt andere drei Teilnehmer und wir retten Irdenen.", completion = "Gute Arbeit! Ihr kämpft wirklich wie Käfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[80513] = { id = 80513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüsselsabotage", description = "Ihr braucht gute Ablenkung, um Irdenen rausholen. Ich müssen Mürrzahnbande aufhalten. Ich haben perfektes Mittel für beides.\n\nIdiot mischen Glutbräu mit Kerzenwachs in Hasenbau. Kerzen brennen erst normal, dann bumm. Großes Bumm. Platziert um Lager herum. Knall gute Ablenkung für Flucht.\n\nWährenddessen Ihr löst Käferleinen. Mürrzahnbande kann sehen wie furchterregend Käfer!", sourceObjective = "Platziert Glutblitzkerzen und lockert die Käferleinen.", completion = "Perfekt, Ihr habt gute Ablenkung, wenn Zeit kommen. Gespannt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[80514] = { id = 80514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berrunds Ausbruch!", description = "Ihr gut gemacht. Jetzt sie Euch lassen in Ring, um \"kämpfen\" gegen Irdenen. Ihr geht in Ring, wenn bereit. Glutblitzkerzen gehen jeden Moment bumm.\n\nIch gehen zurück zu Lager. Warten dort auf Euch und Irdenen.\n\nIhr gute Seele. Nicht sterben.", sourceObjective = "Eskortiert Berrund aus dem Lager.", completion = "Gefangen? Nein, ich habe bloß Informationen gesammelt. Und ich habe schlechte Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[80515] = { id = 80515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Hochglanz poliert", description = "Leider muss zugeben, aber lauter Irdener recht haben. Boss Schnurrpeitsche haben stärkste Käfer. Aber alles haben Schwäche.\n\nSpinnen Angst vor Licht und unser Freund sehr glänzend. Wir machen noch glänzender, dann keine Spinne kämpfen wollen.\n\nMürrzahnbande Kerzenfliegen gesammelt. Ihr befreit und reibt Leuchtstaub ab. Wir machen großen Irdenen groß strahlen!", sourceObjective = "Befreit Kerzenfliegen und sammelt ihre Leuchtkraft ein.", progress = "Hoffentlich steigt ihm das nicht zu Kopfe.", completion = "Ja, dies perfekt. So er wirklich leuchten!", sourceObjectiveStatus = "unverified-source-field" }
quests[80516] = { id = 80516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beseitigung des Bosses", description = "Diese Koboldin weiß wirklich, wovon sie spricht. Laut Skrit hält Boss Schnurrpeitsche seine eigene Spinnenmeute in einer Höhle in der Nähe. Keine Sorge, ich übernehme die Führung.\n\nKommt schon, wir habe einen Boss zu erledigen.", sourceObjective = "Tötet Boss Schnurrpeitsche.", completion = "Ihr zurück! Berrund kommen vorbei. Skrit voller Sorge.\n\nAlles erledigt? Gut. Ohne Anführer Mürrzahnbande bald Geschichte.", sourceObjectiveStatus = "unverified-source-field" }
quests[80517] = { id = 80517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo alles seinen Anfang nahm", description = "<Zet-Zet ist bereit für die Rückkehr zu den Golemwerken der Tiefenschmiede.>", sourceObjective = "Trefft Euch mit Brinthe und Dagran vor den Golemwerken der Tiefenschmiede.", completion = "Gut, Ihr seid hier. Hoffentlich seid Ihr auch bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[80558] = { id = 80558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer nicht wagt", description = "Diese Niffen fristen schon lange ihr Dasein hier unten, lange genug, um ein Dorf zu gründen und Handelsbeziehungen mit den Nerubern aufzubauen. Einige von ihnen handeln sogar in dieser großen nerubischen Stadt!\n\nAber die Goblins? Die sind von der Venture Company. Kein Wunder, dass General Anub'azal mir gegenüber skeptisch war, wenn er den Umgang mit ihnen gewohnt ist.\n\nWas machen sie nur hier unten? Finden wir heraus, was sie an diesen Ort führte.", sourceObjective = "Erfahrt so viel Ihr könnt von den Goblins in Mmarl.", completion = "Sie sind ungehobelt, aber zumindest reden sie mit Euch. Vielleicht könnt Ihr sie davon überzeugen, dass eine Zusammenarbeit für beide Seiten von Vorteil wäre.\n\nVersucht es mit... einer Art Handel. Sie werden das zu schätzen wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80562] = { id = 80562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blühende Gaumenfreude", description = "Nur wenige Anhänger des Lichts würden sich an dem Gericht versuchen, das ich zubereiten möchte. Ein Mix aus traditionellen kaiserlichen Gewürzen und verbotenen Fungusblüten, die hier in der Nähe wachsen.\n\nDas Gericht wird den Gaumen verzücken und den Abenteuergeist in einem wecken, der einst die Heilsturzexpedition möglich gemacht hat.\n\nBegebt Euch bitte zur nahe liegenden Mykomantenhöhle und besorgt mir die Blüten, die ich dafür benötige.", sourceObjective = "Sammelt 20 immerblühende Pilze aus der Mykomantenhöhle.", progress = "Habt Ihr alle Zutaten gefunden?", completion = "Nun wird Magie geschehen. Bitte kostet diese Kreation selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[80563] = { id = 80563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mittel der Einstimmung", description = "Die Neruber müssen sich irgendwie reinigen können, nachdem sie Schwarzem Blut ausgesetzt waren. Wäre das nicht der Fall, wäre ihre Ernteaktion nicht so erfolgreich gewesen.\n\nWenn nötig, kann ich die Harmonie dieser Welt aufnehmen und meinen Geist in dieser Realität wiederherstellen. Aber um Eures und um Hannans willen sollten wir vermutlich beschaffen, was sie verwenden.\n\nWenn es Euch nichts ausmacht, Euer Bewusstsein für den Rest Eures Lebens zwischen zwei Realitäten zu teilen, können wir uns die Scherereien auch sparen.", sourceObjective = "Findet einen Stimmkristall.", progress = "Die Neruber müssen irgendetwas mit sich führen, um ihren Verstand nach der direkten Nähe zu Schwarzblut zu reinigen.", completion = "Ein Stimmkristall? Faszinierend.\n\nObwohl ich sagen muss, dass ich von der Lösung nicht sehr beeindruckt bin. Sie haben sich dieses Problem schließlich selbst eingebrockt.", sourceObjectiveStatus = "unverified-source-field" }
quests[80564] = { id = 80564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldforschung", description = "Die Neruber ernten in der Nähe Schwarzblut.\n\nWenn die Verderbnis, die durch die Ausgrabung der Adern verursacht wurde, fortbesteht, wird sie sich weiter ausbreiten. Sie wird sich so lange ausbreiten, bis sie alles verzehrt hat.\n\nIch habe nicht vor, tatenlos dabei zuzusehen, wie sie die Wurzeln vergiftet. Ich versuche, ihre Methoden zu studieren und zu verstehen... um mitten ins Herz dieser Operation zu stechen.\n\nIhr dürft mir gerne dabei helfen.\n\nInsofern Ihr es auch vorzieht, dass Eure Welt nicht in triefenden Tümpeln aus Schwarzblut ertrinkt, versteht sich.", sourceObjective = "Untersucht das Schwarzblut-Erntegebiet.", completion = "Hier, im Zentrum dieser Verderbnis höre ich, wie mich etwas ruft. Es pocht in meinem Schädel wie eine Trommel.\n\nIch kann es nicht einfach ignorieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[80565] = { id = 80565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallende Rückwirkungen", description = "Es war nicht meine Absicht, dass...\n\n<Orweynas Augenschlitze verengen sich.>\n\nBringt ihn mir, {name}. Ihr seid auch mit dem Schwarzblut in Kontakt gekommen. Doch Hannan hat das meiste davon abbekommen.\n\nEr ist in das Ungehörige gegangen. Als er mit dem Schwarzblut in Berührung kam, ist sein Geist in eine Welt übergegangen, die sich unseren Augen entzieht. Wie weit auch immer er vorgedrungen sein mag, Ihr werdet ihm vermutlich dorthin folgen müssen, um ihn zurückzubringen.\n\nIch werde schon mal für Eure Rückkehr das nerubische Reinigungsinstrument aktivieren.\n\nVerliert Euch nicht in diesem veränderten Zustand.", sourceObjective = "Rettet Hannan aus dem verlassenen Erntegebiet in der Höhle.", progress = "Ist das echt? Bilde ich mir die Monster bloß ein?", completion = "Mein Kopf... Er tut weh. Alles fühlt sich so nebelhaft an... Helft mir, bitte!", sourceObjectiveStatus = "unverified-source-field" }
quests[80566] = { id = 80566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde ohne Ende", description = "<Hannan ist kaum ansprechbar und verfügt über weniger körperliche Substanz, als gut für ihn wäre, da er noch tiefer im Ungehörigen verloren ist als Ihr.>\n\nEin paar Kanister sind explodiert... Dann kamen die Spinnen.\n\nTötet die... Tötet die Spinnen!", sourceObjective = "Findet und tötet die Spinnen.", completion = "Hm. Ich habe bemerkt, dass Ihr gut darin seid, herausfordernde Aufgaben zu überleben. Das werde ich mir merken.", sourceObjectiveStatus = "unverified-source-field" }
quests[80567] = { id = 80567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied der Erneuerung", description = "<Orweyna wirkt beim Anblick von Hannan erleichtert, aber das scheint sie nicht von der Erfüllung ihrer Aufgabe abzubringen.>\n\nWas Ihr in dieser Höhle gefunden habt, überrascht mich ehrlich gesagt nicht. Neruber, die im Ungehörigen feststecken, gefangen in einem Reich voller Monster und Wahnsinn...\n\nIch würde sie ja bemitleiden, doch sie haben sich das selbst zuzuschreiben.\n\nIhr hingegen müsst zurückkommen, bevor das Schwarzblut Euren Geist zu stark beeinträchtigt.", sourceObjective = "Setzt das harmonisierende Instrument ein.", completion = "Sie darf nicht ständig so davonrennen! Der Rest von uns ist ihr hierher gefolgt - wider besseres Wissen, wenn ich hinzufügen darf. Doch wir waren nie damit einverstanden, dass...\n\n<Hannan seufzt.>\n\nNein, wir wussten genau worauf wir uns mit ihr einlassen... Und wir kannten die Konsequenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80568] = { id = 80568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterlasst keine Spur", description = "Ich muss sichergehen, dass es ihr gut geht. Was ich in dieser Höhle gesehen habe... Sollte sie darauf empfindlicher reagieren...\n\n<Hannan knurrt fast schon.>\n\nAber sie bringt sich selbst und uns in Gefahr. Sie zieht alle Aufmerksamkeit auf sich und hinterlässt eine Spur, die Fremde direkt zu ihr führt! Zu uns.\n\nWir müssen dezent sein. Unsichtbar. Wir müssen uns bedeckt halten und uns in unseren anderen Formen verstecken, so oft es geht.\n\nIch bitte Euch nur ungern darum, aber könntet Ihr Euch mit meiner Sense um die Beweise kümmern, während ich nach ihr sehe?", sourceObjective = "Sammelt 10 magische Spuren in Hannans Sense.", completion = "Mir ist es verboten, mit Fremdlingen zu sprechen, aber... Ihr wart eine große Hilfe.\n\nDanke, dass Ihr mir bei dieser Last zur Seite standet.", sourceObjectiveStatus = "unverified-source-field" }
quests[80569] = { id = 80569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harmonische Herangehensweise", description = "Ich weiß, dass ich Orweyna nicht davon abhalten kann, da runterzugehen und die Aufmerksamkeit auf unsere Anwesenheit zu lenken.\n\nAber... vielleicht können wir dafür sorgen, dass sich die Kunde von unserer Gegenwart nicht weiterverbreitet.\n\nWer auch immer für dieses Erntegebiet zuständig ist, findet ihn und... tut, was immer nötig ist, damit er nichts weitersagen kann.", sourceObjective = "Tötet Erntehüter Izk'tilak.", completion = "Ich muss zugeben, ich bin froh, dass Ihr uns bei all dem begleitet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[80570] = { id = 80570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt den Fluss", description = "Wissen die überhaupt, was sie tun?\n\n<Orweyna fletscht die Zähne und knurrt regelrecht.>\n\nZerstört so viele dieser Extraktoren, wie Ihr könnt. Zerschmettert die Glühbirnen, brecht die Glieder und verbrennt die Trümmer.\n\nWir können sie nicht alle aufhalten, nicht heute. Aber ein wenig Zerstörung zügelt vielleicht meinen Zorn.", sourceObjective = "Zerstört 8 Extraktoren.", completion = "Sie haben schon so viel Schaden angerichtet. Die Kreaturen, die einst hier lebten, die Erde, die einst so lebendig war...\n\nWenn wir sie nicht aufhalten können, werden wir uns für alles rächen, das sie unwiederbringlich zerstört haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[80571] = { id = 80571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlüsselt die Kakophonie", description = "Das ist weitaus schlimmer, als ich dachte. Es ist, als würden sie die Verderbnis nähren. Sie befeuern. Die Dissonanz wird immer lauter...\n\n<Orweyna wirkt aufgewühlt, aber unerschrocken.>\n\nIch kann kaum etwas Anderes hören. Mein Kopf pulsiert. Ich... Ich muss wissen, wie verloren dieses Land tatsächlich ist.\n\n{name}. Bringt mir etwas aus dem Ungehörigen.", sourceObjective = "Sammelt 10 disharmonische Essenz von disharmonischen Gegnern im Ungehörigen.", progress = "Was haben die Neruber hier nur angerichetet?", completion = "Das ist falsch. Das ist alles falsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[80572] = { id = 80572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmonische Maßnahmen", description = "Ich ertrage es nicht länger, das mitanzusehen. Ich muss handeln.\n\n{name}. Ihr habt das Ungehörige schon einmal erlebt. Nun müssen wir gemeinsam dorthin gehen. Wenn ich glauben soll, dass dieser abscheuliche Ort tatsächlich nicht gereinigt werden kann, muss ich ihn mit eigenen Augen sehen.\n\nWir töten, was wir können, und vielleicht finden wir einen Hoffnungsschimmer, der uns sagt, dass dieses Land immer noch zu retten ist.", sourceObjective = "Beschafft 50 Stapel 'Ungehörige Verschiebung' und sammelt 3 Proben von Elitegegnern, die im Ungehörigen verloren sind.\n\nWenn Ihr in Lachen aus Schwarzblut steht, könnt Ihr nicht nur Extraktoren zerstören, sondern auch 'Ungehörige Verschiebung' erhalten. Seid jedoch vorsichtig, da Ihr auf diese Weise schnell Stapel erhaltet.", progress = "Hannans Sorgen sind nicht unbegründet.\n\nAber ich kann diese Verderbnis nicht einfach mit ansehen, ohne wenigstens zu versuchen, sie auszurotten.", completion = "<Orweynas Wut spiegelt sich in ihrer leisen Stimme wider, doch ihren Augen wohnt großer Kummer inne.>\n\nDieser Ort ist wahrlich verloren. Was sie hier angerichtet haben, lässt sich nicht wieder rückgängig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80573] = { id = 80573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauschen: Kriegsbeute" }
quests[80576] = { id = 80576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisster Lauscher", description = "Verdammt!\n\nBrennok und ich waren auf dem Weg zur Schattenaderspitze, um ein Rezitationsritual durchzuführen. Wir wurden von Skorpiden angegriffen. Jetzt hat der Schlepper einen Skorpidstachel im Getriebe und Brennok treibt sich sonst wo herum.\n\nEr wollte sich nur kurz die Beine vertreten, während ich den Schlepper wieder flottmache, aber das ist schon ein Weilchen her. Ich muss den Bot wieder in Bewegung setzen, könntet Ihr nach ihm suchen?", sourceObjective = "Findet Brennok.", completion = "Ihr versteht mich falsch, ich wollte die Schallenden Tiefen verlassen. Aber ohne mein Buch geht das jetzt nicht mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[80577] = { id = 80577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezitationsvorbereitungen", description = "Einmal im Jahr nehmen Brennok und ich die lange Route durch die Schallenden Tiefen.\n\nWir halten an jedem Außenposten an, und Brennok erzählt den Bewohnern eine Geschichte aus ihrer Vergangenheit. Eine, die sie ihm anvertraut haben, damit er sie daran erinnern kann, wenn sie sie vergessen.\n\nEs ist meine Pflicht, die Zeremonienstätte vorzubereiten. Würdet Ihr mich begleiten? Ich könnte Eure Hilfe brauchen.", sourceObjective = "Bereitet die Rezitationsstätte vor.", progress = "Brennok ist normalerweise enthusiastischer, wenn es um eine Rezitation geht.", completion = "Vielen Dank. Ich hoffe, Ihr nehmt an der Rezitation teil, wenn es so weit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[80578] = { id = 80578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenarbeiterverkleidung", description = "Ich werde mich nach der Geschichtenrezitation davonschleichen. Es ist ganz einfach, in einer Menge aus Irdenen zu verschwinden, die sich ein Fass Glutbräu zu Gemüte führen.\n\nIch darf aber nicht erkannt werden, wenn ich die Stadt verlasse. Sonst glauben die ja, ich würde meinen Eid verletzen. Da ist es besser, einfach abzuhauen.\n\nWenn Ihr mir eine überzählige Garnitur Minenarbeiterkleidung besorgt, kann ich mich unbemerkt davonstehlen.", sourceObjective = "Findet eine Garnitur Minenarbeiterkleidung.", progress = "Habt Ihr sie schon gefunden?", completion = "Vielen Dank. Darin sollte mich niemand erkennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80592] = { id = 80592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Pakt schmieden", description = "Erneuern wir unseren Pakt.\n\nDenkt daran, Ihr könnt zu jeder Zeit nur mit einem der Durchtrennten Fäden einen Pakt eingehen. Diese Verträge sind jedoch zeitlich begrenzt, also werdet ihr viele Gelegenheiten haben, Euch allen dreien zu beweisen.", sourceObjective = "Wählt einen Pakt mit den Durchtrennten Fäden.", completion = "Mögen sich die Parteien des Pakts gewogen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[80593] = { id = 80593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schluck Glut", description = "Jetzt brauchen wir nur noch eine Sache. Ohne Met wäre es keine richtige Rezitationszeremonie.\n\nDoch Herdhüter Zirc hat mir erzählt, dass die letzten Lieferungen Glutbräu nicht eingetroffen sind. Wie es scheint, gelüstet es den Gaumen hiesiger Schinder in der Grollenden Einöde nach dem Getränk, weshalb sie die Lieferungen plündern.\n\nHier, nehmt ein leeres Fass. Seht, was Ihr von den Schindern bergen könnt.", sourceObjective = "Befüllt ein Fass mit Glutbräumet.", completion = "Vielen Dank, die Minenarbeiter werden das zu schätzen wissen. Ich hoffe, die Schinder haben Euch nicht zu viel Mühe bereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[80670] = { id = 80670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen der Weberin", description = "Die unzähligen Augen der Weberin schleichen durch die Stadt und sammeln so viele Informationen über Ansureks Machenschaften, wie sie können.\n\nDoch Informationen allein werden nicht ausreichen, um das Blatt zu Ungunsten der Streitkräfte der Sureki zu wenden. Die Weberin braucht jemanden, der willens ist, sich die Hände schmutzig zu machen.\n\nIhr könnt Euch wohl glücklich schätzen.", sourceObjective = "Setzt Eure Bemühungen fort, der Weberin in Azj-Kahet zu helfen.", progress = "Tschk-tschaah! Ihr kehrt zurück, immerhin. Welche Neuigkeiten bringt Ihr mir denn aus der Stadt mit?", completion = "Ihr habt großes Talent im Verursachen von Ärger! Gut, gut!\n\nNehmt die hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[80671] = { id = 80671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge des Generals", description = "Selbst in diesem Moment arbeiten General Anub'azals Streitkräfte unermüdlich daran, die Sicherheit von Azj-Kahet zu gewährleisten.\n\nAnsureks Einfluss dringt in jeden Winkel ihres Reichs vor. Der General will ihre militärische Autorität untergraben. Wenn wir ihre Ressourcen ausdünnen, eröffnen sich uns vielleicht neue Gelegenheiten, um zuzuschlagen.", sourceObjective = "Setzt Eure Bemühungen fort, dem General in Azj-Kahet zu helfen.", progress = "Ah, Ihr seid wieder da. Erzählt mir von Euren Triumphen.", completion = "Ihr seid lebendig zurückgekehrt, die Gegner von Anub'azal nicht.\n\nDas gibt Anlass zu Anerkennung!", sourceObjectiveStatus = "unverified-source-field" }
quests[80672] = { id = 80672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand des Wesirs", description = "Der Wesir verbreitet unsere Verschwörung in diesem Moment unter den gut situierten Angehörigen von Azj-Kahets Elite. Doch seine Position hält ihn davon ab, uns direkt zu unterstützen.\n\nDa kommt Ihr ins Spiel. Ihr erlangt immer mehr Ansehen, Euer Ruf eilt Euch voraus. Ihr könnt Euch freier bewegen als der Wesir. Passt nur auf, dass Ihr nicht gefressen werdet, ja?", sourceObjective = "Setzt Eure Bemühungen fort, dem Wesir in Azj-Kahet zu helfen.", completion = "Dank Eurer Bemühungen ist der Wesir der Stärke des Feindes einen Schritt nähergekommen. \n\nDafür ist Euch zu danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[80673] = { id = 80673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Startbahnsäuberung", description = "Hallo!\n\nPläppi und ich sind normalerweise dafür zuständig, während unserer Lampenanzünderpatrouillen den Himmel in diesem Bereich freizumachen. Wenn wir die Motten hier nicht ausmerzen, dann breiten sie sich zu den Himmelsdocks aus und fangen an, ihre Eier in die Maschinerie unserer Schiffe zu legen.\n\nLeider sind wir nicht mehr so flink, wie wir mal waren. Könntet Ihr uns aushelfen? Sie sind recht zart, Hochgeschwindigkeitsflüge setzen ihnen also ziemlich zu. Oder Ihr könnt sie auch einfach auf die altmodische Art und Weise plattmachen.", sourceObjective = "Tötet 25 Motten, indem Ihr durch sie hindurchfliegt oder indem Ihr sie normal tötet.", completion = "Tötet eins davon und vier mehr werden irgendwo auftauchen. Nun, das wird helfen. Wir können uns um den Rest kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[80676] = { id = 80676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungsdefragmentierung", description = "Ich habe geschworen, ein Kompilator zu sein. Ich sammle und erzähle Geschichten unserer Volksleute.\n\n<Brennok seufzt.>\n\nLässt sich Weisheit in Geschichten finden, die von jemandem erzählt werden, der sie nie erlebt hat? Ich habe nie ein Abenteuer erlebt. Ich hatte Angst davor, die Geschichten zu überschreiben, die mir anvertraut wurden.\n\nAlso habe ich angefangen, sie in ein Buch zu übertragen, das ich hier versteckt habe. Jedes Mal, wenn ich nach Schattenaderspitze zurückgekehrt bin, habe ich dem Buch etwas hinzugefügt.\n\nIch wollte gehen und das Buch weitergeben, doch Skorpiden plünderten es. Bitte findet die fehlenden Seiten, ehe sie ihre Nester damit polstern.", sourceObjective = "Sammelt 100 fehlende Seiten von Brennoks Buch.", progress = "Tausende Geschichten, jetzt schmücken sie wahrscheinlich die Höhle irgendeines Tiers...", completion = "Bei den Titanen, habt Dank! Ich weiß nicht, was ich ohne diese Seiten getan hätte.\n\nNun kann ich endlich gehen, ohne meinen Schwur zu brechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80677] = { id = 80677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Eier", description = "Es ist egal, wie viele Motten wir töten, wenn wir uns nicht um die Eier kümmern, dann werden wir immer ein Problem haben.\n\nNehmt diese Waffe und nutzt sie, um hoch droben die Eier in Brand zu stecken.", sourceObjective = "Steckt 15 Motteneier in Brand.", progress = "Gebt auf den Fackelauslöser acht, der ist etwas in die Jahre gekommen.", completion = "Man möchte meinen, dass sie lernen würden, einfach weg zu bleiben. Und doch kommen sie immer wieder zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[80678] = { id = 80678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Zeit", description = "Nun, da die Arbeit erledigt ist... Auf dieser Route habe ich immer nach Wertsachen gestöbert, die von den Docks fallen. Bei der Verladung der Schiffe können kleine Gegenstände herunterfallen. Und manchmal werfen die Leute sie weg, aus Wut, in der Hoffnung auf Glück und so weiter.\n\nManche dieser Gegenstände tragen jedoch Erinnerungen in sich. Dinge, die so wertvoll sind, dass es dem Verlust des eigenen Herzens gleicht. Wenn Ihr mir beim Suchen helfen könntet, wäre ich Euch sehr dankbar.", sourceObjective = "Findet 6 verlorene Andenken.", progress = "Was habt Ihr gefunden?", completion = "Das ist ja eine ordentliche Ausbeute. Nehmt ein paar davon für Euch mit. Vielleicht könnt Ihr ja die Besitzer ausfindig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80679] = { id = 80679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgestopfter Spielzeugluchs", progress = "Der Gegenstand in Eurem Rucksack kommt mir bekannt vor...", completion = "Herr Dünnlich! Ich hatte geglaubt, du wärst für immer verloren!" }
quests[80680] = { id = 80680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befleckter Kompass", progress = "<Der Name auf dem Kompass aus dem Stehmorast entspricht dem in der Inschrift auf dem Gemeinschaftsgrabstein.>", completion = "<Die Welt ist still, abgesehen von dem entfernten Brummen der Luftschiffe. \n\nTrotz der Schäden, die Zeit und Natur angerichtet haben, zeigt die Nadel noch immer Richtung Beledar.>" }
quests[80681] = { id = 80681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochener Armreif", progress = "Was habt Ihr denn da?", completion = "Das ist...\n\n<Keyrra legt den Armreif vorsichtig in ihre Hand.>\n\nIch kann es nicht glauben." }
quests[80682] = { id = 80682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine allerletzte Geschichte", description = "Nun, es ist an der Zeit. Ich werde die Rezitation am Mineneingang halten. Wir sehen uns dort, aber fühlt Euch nicht dazu verpflichtet, bis zum Ende zu bleiben.\n\nIch werde mein Buch für Haimaz zurücklassen. Sie wird sich darum kümmern.\n\nNach der Zeremonie würde ich mich gerne angemessen von Euch verabschieden. Trefft mich an der Brücke außerhalb des Dorfs. Ich werde nach der Rezitation dort hingehen.", sourceObjective = "Nehmt an der Rezitation teil.", completion = "Ich wusste, dass Brennok sich seltsam verhielt. Dann erwähnte einer der Minenarbeiter, dass Ihr Euch eine zusätzliche Garnitur Kleidung ausgeliehen hattet. Zusammen mit seiner komischen Laune verriet mir das, dass er verschwinden wollte.\n\nIch dachte allerdings, dass er hier entlang kommen würde. Habt Ihr ihn gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[80684] = { id = 80684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paarmal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür einen ganz besonderen {race} und außergewöhnlichen {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[80685] = { id = 80685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen am Geschenk steht:\n\nSchöne Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[80689] = { id = 80689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgazurs Fürsorge", description = "Zugewiesene Aufgaben abgeschlossen! Ich schaue auf meiner nächsten geplanten Patrouille wieder nach den Leuten.\n\nEs gibt allerdings noch einen Irdenen, um den ich mich heute kümmern muss. Er bedeutete... er bedeutet mir besonders viel.\n\nIhr wart heute <ein sehr umsichtiger Kollege/eine sehr umsichtige Kollegin>, deshalb möchte ich gern, dass Ihr ihn kennenlernt. Lasst uns etwas gen Westen gehen, näher an die Fälle.", sourceObjective = "Trefft Batzvara an den Schimmernebelfällen.", completion = "Ihr seid hier!\n\n<Sie blickt auf die ausgestreckte Hand des Irdenen neben ihr und seufzt.>\n\nIch muss zugeben, was ich hier vorfand, hat mich ziemlich verstört. Eure Gegenwart ist tröstlich.", sourceObjectiveStatus = "unverified-source-field" }
