quests[81509] = { id = 81509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufe 21" }
quests[81510] = { id = 81510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abtauchen", description = "Was für eine fette Beute! Ich konnte etwas von dem, was wir gefunden haben, Dagran geben, damit er eines seiner Projekte abschließen kann. Er sollte jeden Moment hier sein.\n\nAch, ich halte es nicht mehr aus. Überraschung, es ist ein Geschenk für Euch, das Euch bei Eurer Reise hilft.", sourceObjective = "Sprecht mit Brann Bronzebart.", progress = "Wartet nur, bis Ihr seht, was sich Dagran ausgedacht hat.", completion = "Mit dieser Maschine könnt Ihr Euch auf ganz Khaz Algar bewegen. Wir geben Euch Bescheid, wenn wir neue dafür Teile haben.\n\nDa das nun geklärt wäre: ab in die Tiefen!", sourceObjectiveStatus = "unverified-source-field" }
quests[81512] = { id = 81512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisiten und Räucherwerk" }
quests[81514] = { id = 81514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großzügige Tiefen", description = "Wir werden jede Menge Ressourcen benötigen, um Xal'atath abzuwehren. Doch Ihr habt Glück, denn wir haben eine Quelle aufgetan!\n\nEinige Tiefen, die wir entdeckt haben, bezeichnen wir als \"großzügig\", denn die Bösen horten dort mehr Schätze. Diese Schätze können nur mit speziellen Schlüsseln gehoben werden, die in Khaz Algar verstreut sind.\n\nSchlüssel und Schlüsselfragmente können überall auf der Welt gefunden werden. Macht Euch auf die Suche nach ihnen und stürzt Euch dann in eine großzügige Tiefe!", sourceObjective = "Schließt Spezialauftrag-Weltquests, Weltaktivitäten oder Wöchentliche Quests ab, um einen restaurierten Kastenschlüssel oder Kastenschlüsselsplitter zu erhalten, mit denen Ihr eine Truhe in einer großzügigen Tiefe aufschließen könnt.", completion = "Das hat uns ganz schön was eingebracht! Wollt Ihr Euch noch mehr amüsieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[81555] = { id = 81555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasse Sache: Für einen Zehnt mehr" }
quests[81556] = { id = 81556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Nebel", description = "Freut mich, Euch kennenzulernen. Ihr hättet nicht zufällig Interesse daran, mir bei meinen Forschungen zu helfen?\n\nDie Nebelbestien, die sich seit Kurzem hier eingenistet haben, sind Euch sicher nicht entgangen.\n\nSie werden als schlechtes Omen betrachtet, weil sie immer dann auftauchen, wenn die Umwelt aus dem Gleichgewicht gerät. Ich stimme dieser Annahme nicht zu.\n\nAber da ich mich besonders gut mit dampfbasierter Magie auskenne, hat man mich angeheuert, herauszufinden, woher sie kommen, damit wir sie an der Quelle aufhalten können.", sourceObjective = "Stellt den Nebelsammler auf und sammelt Nebelproben aus verschiedenen Gebieten, in denen sich Nebelbestien aufhalten.", progress = "Habt Ihr die Nebelproben gesammelt?", completion = "Ausgezeichnet! Ich werde die Proben gleich analysieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[81557] = { id = 81557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelmarkierungen", description = "Während ich diese Nebelproben analysiere, habe ich eine andere Aufgabe für Euch.\n\nIch soll für meine Dienstherren herausfinden, woher diese Nebelbestien kommen. Ich habe diese Verfolgungsgeräte entwickelt. Könntet Ihr sie bitte an einer Reihe von Nebelbestien anbringen?\n\nIhr müsst nah herankommen, also ... seid vorsichtig. Hoffentlich haben sie nichts dagegen!", sourceObjective = "Bringt Fährtenleser an Nebelbestien in und um Taelloch an.", completion = "Ihr habt die Fährtenleser angebracht? Perfekt! Haben sie Euch angegriffen? Nein? Interessant... Das ist alles sehr interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[81558] = { id = 81558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnatürliche Raubtiere", description = "Es würde wenig bringen, Nebelbestien zum Erforschen zu markieren, wenn sie kurz darauf sterben, nicht wahr?\n\nKönntet Ihr einige der aggressiven Tiefenschinder erlegen, die sich versammelt haben, um Jagd auf die Nebelbestien zu machen?\n\nAndernfalls sind alle meine Daten vergebens, da bin ich mir sicher.", sourceObjective = "Tötet Tiefenschinderjäger.", completion = "Vielen Dank. Ein Forscher hat die Pflicht, nicht in den Kreislauf der Natur einzugreifen, aber... Ich habe nur eine begrenzte Anzahl an Fährtenlesern.\n\nIch kann nicht riskieren, sie an einen gelangweilten, blutrünstigen Tiefenschinder zu verlieren. Das ist der einzige Grund. Hehe!", sourceObjectiveStatus = "unverified-source-field" }
quests[81559] = { id = 81559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelanhänger", description = "Mit den Fährtenlesern an den Nebelbestien sollten wir herausfinden können, woher sie kommen. Die Fährtenleser hinterlassen eine Spur in der Luft. Für das bloße Auge ist sie unsichtbar, aber mithilfe der Nebel kann ich sie an Orten mit ausreichend hoher Konzentration sichtbar machen.\n\nTheoretisch sollte uns das direkt zu den Stellen führen, an denen sie sich am Häufigsten aufhalten. Vielleicht ein Nest! Über das ich dann meinen Auftraggeber informieren müsste... hm.\n\nNa ja. Mal sehen, was wir in Erfahrung bringen können.", sourceObjective = "Helft Noli, mithilfe ihrer Nebelfährtenlesekunst den Ursprung der Nebelbestien zu finden.", completion = "Wow. Ich meine, wow! Wir haben in so kurzer Zeit so viel gelernt! Aber jetzt müsste ich meinen Auftraggebern Bericht erstatten, die die Tiere loswerden wollen.\n\nIch glaube, die Leute haben ein völlig falsches Bild von den Nebelbestien. Sie greifen nicht an, sofern sie sich nicht bedroht fühlen. Und selbst, als wir ihr Nest betreten haben, haben sie uns sicher fort teleportiert.\n\nWir hatten noch gar keine Gelegenheit, darüber zu sprechen, dass sie zu solcher Magie imstande sind! Fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[81560] = { id = 81560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winters Geschenke", description = "Ich habe gehört, dass Altvater Winter für jeden Geschenke unter den Weihnachtsbaum von Eisenschmiede gelegt hat.\n\nIhr solltet dort auf jeden Fall mal vorbeischauen. Ich bin mir sicher, dass Altvater Winter auch einige Geschenke für Euch mitgebracht hat.", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede.", completion = "Ho, ho, hallo! Ihr seid aus einem ganz bestimmten Grund hier, richtig? Ihr wollt Eure Winterhauchgeschenke endlich öffnen.\n\nNun, macht Euch mal keine Sorgen! Altvater Winter würde doch niemals seinen Liebling vergessen. Schaut einfach unter dem Baum nach, dort findet Ihr Eure Geschenke.\n\nUnd da dies eine Zeit des Gebens ist: Meint Ihr nicht, dass Eure Freunde sich über eines der fantastischen Produkte von Kokelwälder freuen würden?", sourceObjectiveStatus = "unverified-source-field" }
quests[81561] = { id = 81561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winters Geschenke", description = "Ich habe gehört, dass Altvater Winter für jeden Geschenke unter den Weihnachtsbaum von Orgrimmar gelegt hat.\n\nIhr solltet dort auf jeden Fall mal vorbeischauen. Ich bin mir sicher, dass Altvater Winter auch einige Geschenke für Euch mitgebracht hat.", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", completion = "Ho, ho, hallo! Ihr seid aus einem ganz bestimmten Grund hier, richtig? Ihr wollt Eure Winterhauchgeschenke endlich öffnen.\n\nNun, macht Euch mal keine Sorgen! Altvater Winter würde doch niemals seinen Liebling vergessen. Schaut einfach unter dem Baum nach, dort findet Ihr Eure Geschenke.\n\nUnd da dies eine Zeit des Gebens ist: Meint Ihr nicht, dass Eure Freunde sich über einige der fantastischen Produkte von Kokelwälder freuen würden?", sourceObjectiveStatus = "unverified-source-field" }
quests[81564] = { id = 81564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geschichte über Nudeln", description = "Ah, wieder hier zu sein, macht mich glatt hungrig. Habe ich Euch je davon erzählt, wie ich unter Sungshin Eisentatz die Kochkunst erlernt habe?\n\nVielleicht kommt Ihr ja selbst in den Genuss. Ihr müsst es nur sagen, dann bringe ich Euch in eine Version dieser Zeitlinie, in der Ihr... ja, IHR... Euren eigenen Nudelstand betrieben habt!\n\nAlles begann mit dem Geheimrezept der Familie Lin...", sourceObjective = "Sprecht mit Großmeister Jakkus, um das Szenario Die Geheimzutat abzuschließen.", progress = "Mjam, Nudeln...", completion = "Ihr seht also, {name}, die Geheimzutat hatte gar nichts mit dem Gericht zu tun. Was die Nudeln so besonders gemacht hat, war der ausgezeichnete Service.\n\nLasst mich ruhig wissen, wenn Ihr Euch mal wieder über Nudeln unterhalten möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[81565] = { id = 81565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine weitere Runde Nudeln", description = "Nudelnachschlag gefällig?\n\nKein Problem. Ihr müsst es nur sagen, dann bringe ich Euch erneut in eine Version der Vergangenheit, in der Ihr Euren eigenen Nudelstand hattet.", sourceObjective = "Sprecht mit Großmeister Jakkus, um das Szenario Nudelzeit abzuschließen.", completion = "Äußerst schmackhaft, {name}! Ihr seid ein Naturnudeltalent!", sourceObjectiveStatus = "unverified-source-field" }
quests[81568] = { id = 81568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Bestien frei" }
quests[81574] = { id = 81574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporadisches Wachstum", description = "In der nahe gelegenen Mykomantenhöhle breitet sich noch immer unkontrollierter Pilzbewuchs aus. Die jüngste Welle hat alle meine Rekruten in Angst und Schrecken versetzt.\n\nIch brauche dringend Eure Fähigkeiten, um den lästigen Pilzbewuchs zu beseitigen.\n\nNehmt meine Patrouillenfackel und löscht damit Düsterspross und die umliegenden Auswüchse aus. Die Fackel sollte mit dem kleineren Zeug fertig werden, aber Düsterspross erfordert ein direkteres Vorgehen.", sourceObjective = "Tötet Düsterspross und 15 Düstergewächse mit der Patrouillenfackel.", progress = "Habt Ihr die Bedrohung eliminiert?", completion = "Ausgezeichnete Arbeit. Habt Ihr schon einmal über eine Karriere beim Arathimilitär nachgedacht?", sourceObjectiveStatus = "unverified-source-field" }
quests[81587] = { id = 81587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nudelzeit: Bonus" }
quests[81595] = { id = 81595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saisonbeginn", description = "Wir haben jede Menge neue Schätze entdeckt, die man in den Tiefen finden kann! \n\nWir dürfen keine Zeit verplempern. Ich zeige Euch alles, was Ihr wissen müsst, damit Ihr Euch auf die Socken machen könnt!", sourceObjective = "Schaut Euch die Belohnungen an, die von Reno Jackson, Sir Finley Mrrgglton und dem Wegweiser des Tiefenforschers angeboten werden.", completion = "Es geht doch nichts über eine schöne Schatzsuche! Wir werden sie brauchen.\n\nHm? Da hat es aber jemand eilig, herzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[81596] = { id = 81596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenschatzsucher", description = "Einige unserer Forscher sind schwer verletzt aus den Tiefen zurückgekehrt. Sie berichten von einem schrecklichen Monster, das den Namen Zekvir trägt. \n\nVielleicht habt Ihr bereits von dieser Kreatur gehört. Erlaubt mir, Euch mehr darüber zu erzählen, was wir erfahren haben.", sourceObjective = "Findet mehr über Zekvir, Hand der Vorbotin, heraus.", completion = "Dieser Zekvir klingt nach schlechten Neuigkeiten. Wir sollten uns besser vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[81609] = { id = 81609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denk doch bitte jemand an die Kinder!", description = "Seid gegrüßt, {name}. Euch ist sicherlich bewusst, dass es in Azeroth viele Kinder gibt, die keine Familien haben, die sich um sie kümmern. Während der Kinderwoche führen wir uns ihre missliche Lage vor Augen und geben diesen Kindern Hoffnung. Geht Ihr zu ihnen?", sourceObjective = "Sprecht mit Waisenmatrone Nachtigall in Sturmwind oder Ullna in Dornogal.", completion = "Willkommen, {class}. Seid Ihr hier, um den Kindern zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[81610] = { id = 81610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denk doch bitte jemand an die Kinder!", description = "Seid gegrüßt, {name}. Euch ist sicherlich bewusst, dass es in Azeroth viele Kinder gibt, die keine Familien haben, die sich um sie kümmern. Während der Kinderwoche führen wir uns ihre missliche Lage vor Augen und geben diesen Kindern Hoffnung. Geht Ihr zu ihnen?", sourceObjective = "Sprecht mit Waisenmatrone Schlachterbe in Orgrimmar oder Ullna in Dornogal.", completion = "Willkommen, {class}. Seid Ihr hier, um den Kindern zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[81613] = { id = 81613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie soll sich keine Sorgen machen", description = "Richtig, wir sollten zu Haimaz zurückkehren, bevor sie noch misstrauisch wird.\n\nBitte verratet ihr nichts hiervon. Sie hat die Pflicht, mich in meiner Rolle als Kompilator anzuleiten und zu beschützen.\n\nWenn sie wüsste, dass ich vorhabe, fortzugehen... Ich weiß nicht, was sie tun würde.", sourceObjective = "Kehrt zu Haimaz an der Schattenaderspitze zurück.", completion = "Danke, dass Ihr ihn zurückgebracht habt. Er benimmt sich immer so seltsam, wenn wir die Schattenaderspitze erreichen, aber diesmal scheint er noch verstimmter zu sein als üblich.", sourceObjectiveStatus = "unverified-source-field" }
quests[81614] = { id = 81614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Flosse, zwei Flossen, Perlflosse, tote Flosse" }
quests[81615] = { id = 81615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dochtpunkte" }
quests[81620] = { id = 81620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergungsauftrag", sourceObjective = "Zerschmettert Arathivorratskisten und bergt die Luftschiffwerkzeuge.", sourceObjectiveStatus = "unverified-source-field" }
